// 病句 코스 1 — tools/make_bingju.py 가 tools/bingju/c01.json 에서 만든다. 직접 고치지 않는다.
(window.BJ=window.BJ||{})[1]=[[{"o":["故宫始建于明朝永乐四年，历时十四年方才落成，是世界上现存规模最大、保存最为完整的木质结构古建筑群之一。","通过对敦煌莫高窟壁画的数字化扫描，使许多濒临消失的珍贵画面得以永久保存。","研究表明，每天二十分钟左右的午睡不仅能有效缓解疲劳，还有助于巩固记忆、提升下午的专注力。","丝绸之路不仅是一条贸易通道，更是东西方文明交流互鉴的桥梁，深刻影响了沿线各国的宗教、艺术与生活方式。"],"a":1,"type":"주어 결여","why":"“通过……，使……”가 함께 쓰여 문장 전체에 주어가 없다.","fix":"通过对敦煌莫高窟壁画的数字化扫描，许多濒临消失的珍贵画面得以永久保存。","words":[["莫高窟","Mògāo Kū","막고굴(둔황 석굴)"],["濒临","bīnlín","~에 처하다, 직면하다"],["壁画","bìhuà","벽화"],["巩固","gǒnggù","굳히다, 다지다"],["互鉴","hùjiàn","서로 본받다"]],"tr":["고궁은 명나라 영락 4년에 짓기 시작해 14년 만에 완공되었으며, 세계에 현존하는 목조 고건축군 가운데 규모가 가장 크고 가장 온전하게 보존된 곳 중 하나다.","둔황 막고굴 벽화를 디지털로 스캔함으로써 사라질 위기에 놓인 귀중한 화면들이 영구히 보존될 수 있게 되었다.","연구에 따르면 매일 20분 정도의 낮잠은 피로를 효과적으로 풀어 줄 뿐 아니라 기억을 굳히고 오후의 집중력을 높이는 데도 도움이 된다.","실크로드는 무역로였을 뿐 아니라 동서양 문명이 교류하며 서로 배우는 다리였으며, 길 주변 여러 나라의 종교·예술·생활 방식에 깊은 영향을 주었다."],"ow":[[["故宫","Gùgōng","자금성"],["永乐","Yǒnglè","영락(명 연호)"],["落成","luòchéng","준공되다"],["木质结构","mùzhì jiégòu","목조 구조"]],[["莫高窟","Mògāo Kū","막고굴"],["壁画","bìhuà","벽화"],["濒临","bīnlín","~에 처하다"],["扫描","sǎomiáo","스캔하다"]],[["午睡","wǔshuì","낮잠"],["缓解","huǎnjiě","완화하다"],["巩固","gǒnggù","굳히다"],["专注力","zhuānzhùlì","집중력"]],[["丝绸之路","Sīchóu zhī Lù","실크로드"],["互鉴","hùjiàn","서로 본받다"],["沿线","yánxiàn","노선 주변"]]]},{"o":["端午节吃粽子、赛龙舟的习俗，相传与纪念战国时期楚国诗人屈原有关，至今已流传两千多年。","珊瑚礁虽然只占海洋面积的不到百分之一，却孕育了约四分之一的海洋物种，被誉为“海洋中的热带雨林”。","面对日益严峻的水资源短缺问题，许多城市开始推广雨水收集与中水回用技术。","随着高速铁路网络的不断完善，使城市之间的时空距离被大大缩短，“一日生活圈”逐渐成为现实。"],"a":3,"type":"주어 결여","why":"“随着……，使……” 때문에 “时空距离”가 “使”의 목적어가 되어 문장에 주어가 없다.","fix":"随着高速铁路网络的不断完善，城市之间的时空距离被大大缩短，“一日生活圈”逐渐成为现实。","words":[["屈原","Qū Yuán","굴원(전국시대 초나라 시인)"],["珊瑚礁","shānhújiāo","산호초"],["孕育","yùnyù","품어 기르다"],["严峻","yánjùn","심각하다, 엄중하다"],["短缺","duǎnquē","부족하다"]],"tr":["단오절에 쭝쯔를 먹고 용선 경주를 하는 풍습은 전국시대 초나라 시인 굴원을 기리는 일과 관련이 있다고 전해지며, 지금까지 2천여 년 동안 이어져 왔다.","산호초는 바다 면적의 1%도 차지하지 않지만 해양 생물종의 약 4분의 1을 길러 내어 ‘바닷속 열대 우림’이라 불린다.","날로 심각해지는 물 부족 문제에 맞서 많은 도시가 빗물 모으기와 중수 재활용 기술을 보급하기 시작했다.","고속철도망이 계속 완비되면서 도시 사이의 시간·공간 거리가 크게 줄어들었고 ‘하루 생활권’이 점점 현실이 되었다."],"ow":[[["粽子","zòngzi","쭝쯔(대나무 잎 찹쌀밥)"],["龙舟","lóngzhōu","용선"],["屈原","Qū Yuán","굴원"],["相传","xiāngchuán","~라고 전해지다"]],[["珊瑚礁","shānhújiāo","산호초"],["孕育","yùnyù","품어 기르다"],["物种","wùzhǒng","생물종"]],[["严峻","yánjùn","심각하다"],["短缺","duǎnquē","부족하다"],["推广","tuīguǎng","보급하다"]],[["完善","wánshàn","완비되다"],["缩短","suōduǎn","단축하다"],["生活圈","shēnghuóquān","생활권"]]]},{"o":["在几代科研人员的不懈努力下，让杂交水稻的亩产量屡创新高，为保障粮食安全作出了巨大贡献。","北宋画家张择端的《清明上河图》以长卷形式，生动再现了汴京城内外繁华热闹的市井风貌。","适当的压力能够激发人的潜能，但长期处于高压状态，则容易导致焦虑和免疫力下降。","长城并非一次修建而成，而是自春秋战国起历经多个朝代不断修筑、连接而成的庞大防御工程。"],"a":0,"type":"주어 결여","why":"“在……下，让……” 때문에 “亩产量”이 “让”의 목적어가 되어 주어가 없다.","fix":"在几代科研人员的不懈努力下，杂交水稻的亩产量屡创新高，为保障粮食安全作出了巨大贡献。","words":[["不懈","búxiè","게을리하지 않다"],["杂交水稻","zájiāo shuǐdào","교잡 벼"],["屡创新高","lǚ chuàng xīn gāo","거듭 최고치를 경신하다"],["汴京","Biànjīng","변경(북송의 수도)"],["市井","shìjǐng","저잣거리"],["潜能","qiánnéng","잠재력"]],"tr":["여러 세대 연구자들의 꾸준한 노력으로 교잡 벼의 단위 면적당 생산량이 거듭 최고치를 경신해 식량 안보에 큰 공헌을 했다.","북송 화가 장택단의 《청명상하도》는 긴 두루마리 형식으로 변경성 안팎의 번화하고 떠들썩한 거리 풍경을 생생하게 재현했다.","적당한 스트레스는 사람의 잠재력을 끌어내지만, 오래도록 높은 스트레스 속에 있으면 불안과 면역력 저하로 이어지기 쉽다.","만리장성은 한 번에 지어진 것이 아니라 춘추전국시대부터 여러 왕조를 거치며 계속 쌓고 이어 붙여 만든 거대한 방어 시설이다."],"ow":[[["不懈","búxiè","게을리하지 않다"],["杂交水稻","zájiāo shuǐdào","교잡 벼"],["亩产量","mǔchǎnliàng","무당 생산량"],["屡创新高","lǚ chuàng xīn gāo","거듭 최고치를 경신하다"]],[["张择端","Zhāng Zéduān","장택단"],["清明上河图","Qīngmíng Shànghé Tú","청명상하도"],["汴京","Biànjīng","변경(북송 수도)"],["市井","shìjǐng","저잣거리"]],[["激发","jīfā","끌어내다"],["潜能","qiánnéng","잠재력"],["焦虑","jiāolǜ","불안"],["免疫力","miǎnyìlì","면역력"]],[["春秋战国","Chūnqiū Zhànguó","춘추전국"],["朝代","cháodài","왕조"],["修筑","xiūzhù","쌓다"],["庞大","pángdà","거대하다"]]]},{"o":["苏州园林讲究移步换景，亭台楼阁与假山池沼错落有致，堪称中国古典园林艺术的典范。","考拉每天要睡十八到二十个小时，这是因为它们以营养价值很低的桉树叶为食，需要尽量减少能量消耗。","由于他在青铜器铭文研究领域的开创性贡献，令这位学者在国际汉学界享有很高的声誉。","尽管电子支付已十分普及，但在一些偏远山区，现金仍是当地居民最常用的交易方式。"],"a":2,"type":"주어 결여","why":"“由于……，令……” 때문에 “这位学者”가 “令”의 목적어가 되어 문장에 주어가 없다.","fix":"由于在青铜器铭文研究领域的开创性贡献，这位学者在国际汉学界享有很高的声誉。","words":[["移步换景","yí bù huàn jǐng","걸음마다 경치가 바뀌다"],["错落有致","cuò luò yǒu zhì","들쭉날쭉하면서도 조화롭다"],["堪称","kānchēng","~라 할 만하다"],["桉树","ānshù","유칼립투스"],["铭文","míngwén","명문(새긴 글)"],["汉学","hànxué","중국학"]],"tr":["쑤저우 원림은 걸음마다 경치가 바뀌도록 꾸미는 것을 중시하며, 정자·누각과 가산·연못이 조화롭게 어우러져 중국 고전 원림 예술의 본보기라 할 만하다.","코알라는 하루에 18~20시간을 자는데, 영양가가 매우 낮은 유칼립투스 잎을 먹고 살아서 에너지 소모를 되도록 줄여야 하기 때문이다.","청동기 명문 연구 분야에서 이룬 선구적인 공헌으로 이 학자는 국제 중국학계에서 높은 명성을 누리고 있다.","전자 결제가 이미 널리 퍼졌지만 일부 외딴 산간 지역에서는 현금이 여전히 주민들이 가장 많이 쓰는 거래 수단이다."],"ow":[[["园林","yuánlín","정원"],["移步换景","yí bù huàn jǐng","걸음마다 경치가 바뀌다"],["错落有致","cuò luò yǒu zhì","들쭉날쭉하면서 조화롭다"],["堪称","kānchēng","~라 할 만하다"],["典范","diǎnfàn","본보기"]],[["考拉","kǎolā","코알라"],["桉树","ānshù","유칼립투스"],["消耗","xiāohào","소모"]],[["铭文","míngwén","명문(새긴 글)"],["开创性","kāichuàngxìng","선구적인"],["汉学","hànxué","중국학"],["声誉","shēngyù","명성"]],[["普及","pǔjí","보급되다"],["偏远","piānyuǎn","외지다"],["交易","jiāoyì","거래"]]]},{"o":["二十四节气是古人通过观察太阳周年运动而总结出的知识体系，被列入联合国教科文组织人类非物质文化遗产代表作名录。","候鸟之所以能够在数千公里的迁徙中准确辨别方向，是因为它们可以感知地球磁场的变化。","近年来，各地文物部门针对古建筑屋顶漏雨、木构件腐朽等问题，及时有效的修缮措施。","与其盲目追求所谓的“速成”，不如脚踏实地，在日积月累中夯实自己的专业基础。"],"a":2,"type":"술어 결여","why":"“针对……问题” 뒤에 “及时有效的修缮措施”만 있고 “采取了” 같은 동사가 없다.","fix":"近年来，各地文物部门针对古建筑屋顶漏雨、木构件腐朽等问题，采取了及时有效的修缮措施。","words":[["节气","jiéqi","절기"],["迁徙","qiānxǐ","이동하다, 옮겨 가다"],["磁场","cíchǎng","자기장"],["腐朽","fǔxiǔ","썩다"],["修缮","xiūshàn","보수하다"],["夯实","hāngshí","단단히 다지다"]],"tr":["24절기는 옛사람들이 태양의 한 해 운행을 관찰해 정리한 지식 체계로, 유네스코 인류무형문화유산 대표목록에 올랐다.","철새가 수천 킬로미터를 이동하면서도 방향을 정확히 가려낼 수 있는 것은 지구 자기장의 변화를 느낄 수 있기 때문이다.","최근 몇 년 사이 각지의 문화재 부서는 옛 건물 지붕의 누수, 목재 부재의 부식 같은 문제에 대해 신속하고 효과적인 보수 조치를 취했다.","이른바 ‘속성’을 무작정 좇기보다는 착실하게 한 걸음씩 나아가며 오랜 시간 쌓아서 자신의 전문 기초를 단단히 다지는 편이 낫다."],"ow":[[["节气","jiéqi","절기"],["联合国教科文组织","Liánhéguó Jiàokēwén Zǔzhī","유네스코"],["非物质文化遗产","fēi wùzhì wénhuà yíchǎn","무형문화유산"],["名录","mínglù","목록"]],[["候鸟","hòuniǎo","철새"],["迁徙","qiānxǐ","이동하다"],["辨别","biànbié","가려내다"],["磁场","cíchǎng","자기장"]],[["文物","wénwù","문화재"],["构件","gòujiàn","부재"],["腐朽","fǔxiǔ","썩다"],["修缮","xiūshàn","보수하다"]],[["盲目","mángmù","무작정"],["速成","sùchéng","속성"],["脚踏实地","jiǎo tà shí dì","착실하다"],["日积月累","rì jī yuè lěi","오랜 시간 쌓다"],["夯实","hāngshí","단단히 다지다"]]]},{"o":["这部纪录片以细腻的镜头语言，对宋代汝窑瓷器从选料、拉坯到施釉、烧制的全过程。","据统计，我国现存古籍数量浩繁，其中相当一部分亟待整理与修复。","冬季长期待在门窗紧闭的室内，空气不流通，人们更容易感染呼吸道疾病。","他在实验中屡遭失败，却从未因此气馁，而是一次次调整方案，最终取得了突破。"],"a":0,"type":"술어 결여","why":"“对……全过程” 개사구만 있고 그 뒤에 “进行了记录” 같은 술어가 없다.","fix":"这部纪录片以细腻的镜头语言，对宋代汝窑瓷器从选料、拉坯到施釉、烧制的全过程进行了完整的记录。","words":[["细腻","xìnì","섬세하다"],["汝窑","Rǔyáo","여요(송대 명요)"],["施釉","shīyòu","유약을 바르다"],["浩繁","hàofán","방대하다"],["亟待","jídài","시급히 ~해야 하다"],["气馁","qìněi","기가 꺾이다"]],"tr":["이 다큐멘터리는 섬세한 촬영 기법으로 송대 여요 자기를 재료 고르기, 성형, 유약 바르기, 굽기까지 전 과정을 빠짐없이 기록했다.","통계에 따르면 우리나라에 남아 있는 고서는 수가 매우 많으며, 그중 상당수는 정리와 복원이 시급하다.","겨울에 문과 창을 꼭 닫은 실내에 오래 있으면 공기가 통하지 않아 호흡기 질환에 더 쉽게 걸린다.","그는 실험에서 여러 번 실패했지만 그 때문에 기죽지 않고 계속 방안을 고쳐 마침내 돌파구를 찾았다."],"ow":[[["纪录片","jìlùpiàn","다큐멘터리"],["细腻","xìnì","섬세하다"],["汝窑","Rǔyáo","여요"],["拉坯","lāpī","물레 성형"],["施釉","shī yòu","유약을 바르다"]],[["古籍","gǔjí","고서"],["浩繁","hàofán","방대하다"],["亟待","jídài","시급히 ~해야 하다"],["修复","xiūfù","복원하다"]],[["紧闭","jǐnbì","꼭 닫다"],["流通","liútōng","통하다"],["呼吸道","hūxīdào","호흡기"]],[["屡遭","lǚzāo","여러 번 겪다"],["气馁","qìněi","기가 꺾이다"],["突破","tūpò","돌파"]]]},{"o":["明代科学家宋应星所著的《天工开物》，系统记载了农业和手工业的生产技术，被誉为“中国十七世纪的工艺百科全书”。","骆驼的驼峰里储存的并不是水，而是脂肪，这些脂肪在食物匮乏时可以分解，为身体提供能量。","这座小城依山傍水，气候宜人，每逢周末都会吸引大批游客前来观光度假。","为了让更多年轻人了解古老的昆曲艺术，这家剧院近年来在剧目编排和舞台呈现方面的大胆创新。"],"a":3,"type":"술어 결여","why":"“在……方面的大胆创新”은 명사구일 뿐이고 “进行了” 같은 술어가 빠졌다.","fix":"为了让更多年轻人了解古老的昆曲艺术，这家剧院近年来在剧目编排和舞台呈现方面进行了大胆创新。","words":[["天工开物","Tiāngōng Kāiwù","천공개물(명대 기술서)"],["驼峰","tuófēng","낙타 혹"],["匮乏","kuìfá","결핍되다"],["依山傍水","yī shān bàng shuǐ","산을 등지고 물에 접하다"],["昆曲","kūnqǔ","곤곡(전통 희곡)"],["呈现","chéngxiàn","드러내다, 보여 주다"]],"tr":["명대 과학자 송응성이 쓴 《천공개물》은 농업과 수공업의 생산 기술을 체계적으로 기록해 ‘중국 17세기의 공예 백과사전’으로 불린다.","낙타의 혹에 저장된 것은 물이 아니라 지방이며, 이 지방은 먹이가 부족할 때 분해되어 몸에 에너지를 공급한다.","이 작은 도시는 산을 등지고 물가에 있으며 기후가 쾌적해 주말마다 많은 관광객이 휴가를 즐기러 찾아온다.","더 많은 젊은이가 오래된 곤곡 예술을 알게 하려고, 이 극장은 최근 몇 년 동안 작품 구성과 무대 연출에서 과감한 혁신을 했다."],"ow":[[["宋应星","Sòng Yìngxīng","송응성"],["天工开物","Tiāngōng Kāiwù","천공개물"],["记载","jìzǎi","기록하다"],["百科全书","bǎikē quánshū","백과사전"]],[["驼峰","tuófēng","낙타 혹"],["脂肪","zhīfáng","지방"],["匮乏","kuìfá","부족하다"],["分解","fēnjiě","분해하다"]],[["依山傍水","yī shān bàng shuǐ","산을 등지고 물에 접하다"],["宜人","yírén","쾌적하다"],["观光","guānguāng","관광하다"]],[["昆曲","kūnqǔ","곤곡"],["剧目","jùmù","공연 작품"],["编排","biānpái","구성하다"],["呈现","chéngxiàn","보여 주다"]]]},{"o":["茶叶最早被用作药材，到了唐代，饮茶之风才盛行于全国，陆羽还为此撰写了世界上第一部茶学专著《茶经》。","造纸术的发明大大降低了书写材料的成本，扩大了知识在社会各阶层中传播的。","当地政府出台了一系列优惠政策，鼓励大学毕业生返乡创业，带动了乡村经济的发展。","成年人体重的百分之六十左右来自水分，即使是轻度脱水，也可能引起注意力下降、头痛乏力等症状。"],"a":1,"type":"목적어·중심어 결여","why":"“扩大了……传播的” 뒤에 중심어 “范围”가 없어 목적어가 완성되지 않았다.","fix":"造纸术的发明大大降低了书写材料的成本，扩大了知识在社会各阶层中传播的范围。","words":[["盛行","shèngxíng","성행하다"],["撰写","zhuànxiě","저술하다"],["专著","zhuānzhù","전문 저서"],["阶层","jiēcéng","계층"],["脱水","tuōshuǐ","탈수"]],"tr":["찻잎은 처음에 약재로 쓰였고 당대에 이르러서야 차 마시는 풍습이 전국에 퍼졌으며, 육우는 이를 위해 세계 최초의 차 전문서 《다경》을 썼다.","제지술의 발명은 필기 재료의 비용을 크게 낮추었고, 지식이 사회 각 계층에 퍼지는 범위를 넓혔다.","현지 정부는 일련의 우대 정책을 내놓아 대학 졸업생이 고향으로 돌아가 창업하도록 장려했고, 농촌 경제의 발전을 이끌었다.","성인 체중의 60% 정도는 수분이며, 가벼운 탈수만으로도 집중력 저하, 두통, 무기력 같은 증상이 생길 수 있다."],"ow":[[["药材","yàocái","약재"],["盛行","shèngxíng","성행하다"],["陆羽","Lù Yǔ","육우"],["撰写","zhuànxiě","저술하다"],["专著","zhuānzhù","전문 저서"]],[["造纸术","zàozhǐshù","제지술"],["阶层","jiēcéng","계층"],["传播","chuánbō","퍼지다"]],[["出台","chūtái","내놓다"],["优惠","yōuhuì","우대"],["创业","chuàngyè","창업하다"],["带动","dàidòng","이끌다"]],[["脱水","tuōshuǐ","탈수"],["乏力","fálì","기운이 없다"],["症状","zhèngzhuàng","증상"]]]},{"o":["这次考古发掘出土的大量陶器、玉器和青铜器，为研究商代中晚期的社会结构和祭祀礼仪提供了极其宝贵的。","春节前夕，各地火车站人流如织，数以亿计的人踏上归途，这被称为“人类历史上规模最大的周期性迁徙”。","蜜蜂能通过特定的“舞蹈”向同伴传递蜜源的方向和距离，揭示这一奥秘的奥地利学者弗里施后来荣获了诺贝尔奖。","面对突如其来的变故，她并没有惊慌失措，而是冷静地分析形势，迅速制定了应对方案。"],"a":0,"type":"목적어·중심어 결여","why":"“提供了极其宝贵的” 뒤에 “实物资料” 같은 목적어가 없다.","fix":"这次考古发掘出土的大量陶器、玉器和青铜器，为研究商代中晚期的社会结构和祭祀礼仪提供了极其宝贵的实物资料。","words":[["发掘","fājué","발굴하다"],["祭祀","jìsì","제사 지내다"],["人流如织","rén liú rú zhī","사람들이 끊임없이 오가다"],["揭示","jiēshì","밝혀내다"],["奥秘","àomì","신비, 비밀"],["惊慌失措","jīng huāng shī cuò","놀라 어쩔 줄 모르다"]],"tr":["이번 발굴에서 나온 많은 도기·옥기·청동기는 상나라 중후기의 사회 구조와 제사 의례를 연구하는 데 매우 귀중한 실물 자료가 되었다.","춘절을 앞두고 각지 기차역은 사람들로 붐비고 수억 명이 귀성길에 오르는데, 이를 ‘인류 역사상 가장 큰 주기적 이동’이라 부른다.","꿀벌은 특정한 ‘춤’으로 동료에게 꿀이 있는 곳의 방향과 거리를 알려 주는데, 이 비밀을 밝힌 오스트리아 학자 프리슈는 뒤에 노벨상을 받았다.","갑작스러운 변고 앞에서 그녀는 당황하지 않고 침착하게 상황을 분석해 재빨리 대응책을 세웠다."],"ow":[[["发掘","fājué","발굴하다"],["出土","chūtǔ","출토되다"],["玉器","yùqì","옥기"],["祭祀","jìsì","제사"]],[["前夕","qiánxī","전날"],["人流如织","rén liú rú zhī","사람들이 끊임없이 오가다"],["数以亿计","shù yǐ yì jì","수억에 이르다"],["迁徙","qiānxǐ","이동"]],[["蜜源","mìyuán","밀원"],["揭示","jiēshì","밝혀내다"],["奥秘","àomì","비밀"],["荣获","rónghuò","영예롭게 받다"]],[["突如其来","tū rú qí lái","갑작스럽다"],["变故","biàngù","변고"],["惊慌失措","jīng huāng shī cuò","놀라 어쩔 줄 모르다"]]]},{"o":["适量摄入膳食纤维，有助于促进肠道蠕动，维持肠道菌群的平衡。","这位作家擅长从平凡的日常生活中挖掘深刻的哲理，因此她的散文读来朴素却耐人寻味。","李冰主持修建的都江堰水利工程，两千多年来一直发挥着防洪灌溉的，使成都平原成为沃野千里的“天府之国”。","互联网的普及在给人们带来便利的同时，也使个人信息泄露的风险与日俱增。"],"a":2,"type":"목적어·중심어 결여","why":"“发挥着防洪灌溉的” 뒤에 중심어 “作用”이 빠졌다.","fix":"李冰主持修建的都江堰水利工程，两千多年来一直发挥着防洪灌溉的作用，使成都平原成为沃野千里的“天府之国”。","words":[["膳食纤维","shànshí xiānwéi","식이섬유"],["蠕动","rúdòng","연동 운동하다"],["耐人寻味","nài rén xún wèi","곱씹을 만하다"],["都江堰","Dūjiāngyàn","도강언(고대 수리 시설)"],["灌溉","guàngài","관개하다"],["沃野千里","wò yě qiān lǐ","끝없이 펼쳐진 기름진 들"],["与日俱增","yǔ rì jù zēng","날로 늘어나다"]],"tr":["식이섬유를 적당히 섭취하면 장의 연동 운동을 돕고 장내 세균의 균형을 유지하는 데 좋다.","이 작가는 평범한 일상에서 깊은 철학을 캐내는 데 뛰어나서, 그녀의 산문은 소박하면서도 곱씹을 맛이 있다.","이빙이 주도해 만든 도강언 수리 시설은 2천여 년 동안 홍수를 막고 논밭에 물을 대는 역할을 해 와 청두 평원을 끝없이 기름진 ‘천부지국’으로 만들었다.","인터넷의 보급은 사람들에게 편리함을 주는 동시에 개인 정보가 새어 나갈 위험도 나날이 키우고 있다."],"ow":[[["摄入","shèrù","섭취하다"],["膳食纤维","shànshí xiānwéi","식이섬유"],["蠕动","rúdòng","연동 운동하다"],["菌群","jūnqún","세균 무리"]],[["擅长","shàncháng","뛰어나다"],["挖掘","wājué","캐내다"],["哲理","zhélǐ","철학적 이치"],["耐人寻味","nài rén xún wèi","곱씹을 만하다"]],[["李冰","Lǐ Bīng","이빙"],["都江堰","Dūjiāngyàn","도강언"],["灌溉","guàngài","관개하다"],["沃野千里","wò yě qiān lǐ","끝없이 기름진 들"],["天府之国","tiānfǔ zhī guó","천부지국(풍요로운 땅)"]],[["普及","pǔjí","보급"],["泄露","xièlòu","새다"],["与日俱增","yǔ rì jù zēng","날로 늘다"]]]}],[{"o":["中秋赏月的习俗始于魏晋，盛于唐宋，明清以后，“团圆”逐渐成为这个节日的核心寓意。","研究人员发现，长期睡眠不足会削弱人体的免疫功能，增加罹患心血管疾病的风险。","秦始皇陵兵马俑一号坑东西长约230米左右，坑内排列着数以千计的陶制武士俑和战马。","这家企业凭借自主研发的核心技术，在短短几年内便跻身行业前列。"],"a":2,"type":"어림수 중복","why":"“约”와 “左右”가 둘 다 어림을 나타내어 겹친다.","fix":"秦始皇陵兵马俑一号坑东西长约230米，坑内排列着数以千计的陶制武士俑和战马。","words":[["寓意","yùyì","담긴 뜻"],["削弱","xuēruò","약화시키다"],["罹患","líhuàn","(병에) 걸리다"],["兵马俑","bīngmǎyǒng","병마용"],["跻身","jīshēn","(대열에) 들어서다"]],"tr":["중추절에 달을 감상하는 풍습은 위진 시대에 시작해 당송 때 성행했고, 명청 이후에는 ‘단란한 모임’이 이 명절의 핵심 의미가 되었다.","연구진은 오랫동안 잠이 부족하면 몸의 면역 기능이 약해지고 심혈관 질환에 걸릴 위험이 커진다는 사실을 발견했다.","진시황릉 병마용 1호갱은 동서 길이가 약 230미터이며, 갱 안에는 수천 점의 도제 무사상과 전마가 늘어서 있다.","이 기업은 자체 개발한 핵심 기술을 바탕으로 불과 몇 년 만에 업계 선두권에 들었다."],"ow":[[["魏晋","Wèi-Jìn","위진"],["团圆","tuányuán","가족이 모이다"],["寓意","yùyì","담긴 뜻"]],[["削弱","xuēruò","약화시키다"],["免疫","miǎnyì","면역"],["罹患","líhuàn","(병에) 걸리다"],["心血管","xīnxuèguǎn","심혈관"]],[["秦始皇陵","Qín Shǐhuáng Líng","진시황릉"],["兵马俑","bīngmǎyǒng","병마용"],["数以千计","shù yǐ qiān jì","수천에 이르다"]],[["凭借","píngjiè","~을 바탕으로"],["研发","yánfā","연구 개발하다"],["跻身","jīshēn","들어서다"]]]},{"o":["据史书记载，郑和率领的船队规模庞大，最多时有将近两百多艘船只、两万余名船员。","黄山以奇松、怪石、云海、温泉“四绝”闻名于世，自古便有“五岳归来不看山，黄山归来不看岳”的美誉。","一些心理学家认为，适度的“无聊”反而能够激发人的创造力，促使大脑产生新的想法。","由于过度捕捞和栖息地遭到破坏，长江白鲟已被宣布灭绝，这一消息令人扼腕。"],"a":0,"type":"어림수 중복","why":"“将近”(조금 못 미침)과 “多”(넘음)가 함께 쓰여 뜻이 겹치고 모순된다.","fix":"据史书记载，郑和率领的船队规模庞大，最多时有两百多艘船只、两万余名船员。","words":[["郑和","Zhèng Hé","정화(명대 항해가)"],["五岳","Wǔ Yuè","오악(다섯 명산)"],["栖息地","qīxīdì","서식지"],["白鲟","báixún","중국주걱철갑상어"],["扼腕","èwàn","안타까워하다"]],"tr":["역사서의 기록에 따르면 정화가 이끈 선단은 규모가 거대해, 가장 많을 때는 배가 이백 척 가까이, 선원이 2만여 명에 이르렀다.","황산은 기이한 소나무, 괴석, 운해, 온천의 ‘네 가지 절경’으로 이름나 있고, 예로부터 ‘오악을 보고 오면 다른 산은 볼 것이 없고, 황산을 보고 오면 오악도 볼 것이 없다’는 찬사를 받아 왔다.","일부 심리학자들은 적당한 ‘지루함’이 오히려 창의력을 끌어내고 뇌가 새로운 생각을 하도록 이끈다고 본다.","남획과 서식지 파괴로 장강 주걱철갑상어는 멸종이 선언되었으며, 이 소식은 사람들을 안타깝게 했다."],"ow":[[["郑和","Zhèng Hé","정화"],["率领","shuàilǐng","이끌다"],["庞大","pángdà","거대하다"]],[["黄山","Huáng Shān","황산"],["怪石","guàishí","괴석"],["五岳","Wǔ Yuè","오악"],["美誉","měiyù","명성"]],[["激发","jīfā","끌어내다"],["创造力","chuàngzàolì","창의력"],["促使","cùshǐ","~하게 하다"]],[["捕捞","bǔlāo","어획하다"],["栖息地","qīxīdì","서식지"],["白鲟","báixún","주걱철갑상어"],["扼腕","èwàn","안타까워하다"]]]},{"o":["活字印刷术由北宋平民毕昇发明，比欧洲同类技术早了约四百年。","不少年轻人选择利用业余时间学习书法、茶艺等传统技艺，以此陶冶情操、缓解压力。","新能源汽车产业的迅猛发展，对动力电池的安全性与续航能力提出了更高的要求。","受地形影响，这一地区南北两侧的年降水量悬殊很大，植被类型也截然不同。"],"a":3,"type":"단어 안의 뜻 반복","why":"“悬殊”가 이미 ‘차이가 매우 크다’는 뜻이라 “很大”가 군더더기다.","fix":"受地形影响，这一地区南北两侧的年降水量相差很大，植被类型也截然不同。","words":[["毕昇","Bì Shēng","필승(활자 발명가)"],["陶冶情操","táo yě qíng cāo","정서를 함양하다"],["续航","xùháng","(배터리) 지속 주행"],["悬殊","xuánshū","차이가 크다"],["截然不同","jié rán bù tóng","완전히 다르다"]],"tr":["활자 인쇄술은 북송의 평민 필승이 발명했으며, 유럽의 같은 기술보다 약 400년 앞섰다.","적지 않은 젊은이들이 여가 시간에 서예·다도 같은 전통 기예를 배우며 정서를 가꾸고 스트레스를 푼다.","신에너지 자동차 산업이 빠르게 발전하면서 동력 배터리의 안전성과 주행 지속 능력에 더 높은 요구가 제기되었다.","지형의 영향으로 이 지역 남북 양쪽의 연 강수량은 차이가 매우 크고 식생 유형도 완전히 다르다."],"ow":[[["活字印刷术","huózì yìnshuāshù","활자 인쇄술"],["毕昇","Bì Shēng","필승"]],[["书法","shūfǎ","서예"],["茶艺","cháyì","다도"],["陶冶情操","táo yě qíng cāo","정서를 함양하다"]],[["迅猛","xùnměng","빠르고 맹렬하다"],["动力电池","dònglì diànchí","동력 배터리"],["续航","xùháng","주행 지속"]],[["降水量","jiàngshuǐliàng","강수량"],["悬殊","xuánshū","차이가 크다"],["植被","zhíbèi","식생"],["截然不同","jié rán bù tóng","완전히 다르다"]]]},{"o":["京剧融合了唱、念、做、打等多种表演形式，脸谱的颜色更是暗示着人物的性格与忠奸。","举办这次非物质文化遗产展览的目的，是为了让更多市民近距离感受传统手工艺的独特魅力。","海豚睡觉时只有一半大脑休息，另一半则保持清醒，以便随时浮出水面换气并警惕天敌。","他毕业后放弃了大城市的高薪工作，回到家乡从事生态农业，如今已带动几十户村民脱贫致富。"],"a":1,"type":"단어 안의 뜻 반복","why":"“目的是”와 “为了”가 같은 뜻이라 겹친다.","fix":"举办这次非物质文化遗产展览的目的，是让更多市民近距离感受传统手工艺的独特魅力。","words":[["脸谱","liǎnpǔ","(경극) 얼굴 분장"],["忠奸","zhōngjiān","충신과 간신"],["非物质文化遗产","fēi wùzhì wénhuà yíchǎn","무형문화유산"],["警惕","jǐngtì","경계하다"],["脱贫致富","tuō pín zhì fù","가난을 벗고 부유해지다"]],"tr":["경극은 노래·대사·연기·무술 등 여러 표현 방식을 아우르며, 얼굴 분장의 색은 인물의 성격과 충신·간신 여부를 암시하기도 한다.","이번 무형문화유산 전시회를 연 목적은 더 많은 시민이 전통 수공예의 독특한 매력을 가까이에서 느끼게 하려는 것이다.","돌고래는 잘 때 뇌의 절반만 쉬고 나머지 절반은 깨어 있어서, 언제든 수면으로 올라와 숨을 쉬고 천적을 경계할 수 있다.","그는 졸업 후 대도시의 고연봉 일자리를 포기하고 고향으로 돌아가 생태 농업에 종사했고, 지금은 수십 가구의 마을 사람을 가난에서 벗어나게 했다."],"ow":[[["京剧","jīngjù","경극"],["脸谱","liǎnpǔ","얼굴 분장"],["暗示","ànshì","암시하다"],["忠奸","zhōngjiān","충신과 간신"]],[["非物质文化遗产","fēi wùzhì wénhuà yíchǎn","무형문화유산"],["手工艺","shǒugōngyì","수공예"],["魅力","mèilì","매력"]],[["海豚","hǎitún","돌고래"],["警惕","jǐngtì","경계하다"],["天敌","tiāndí","천적"]],[["生态农业","shēngtài nóngyè","생태 농업"],["带动","dàidòng","이끌다"],["脱贫致富","tuō pín zhì fù","가난을 벗고 부유해지다"]]]},{"o":["植物的根系不仅能够吸收水分和养分，还能固定土壤，有效防止水土流失。","宋代是中国古代科技发展的一个高峰，这一时期涌现出了沈括、苏颂等一大批杰出科学家出现。","随着人口老龄化程度的加深，如何完善养老服务体系已成为社会各界普遍关注的焦点。","这部小说的情节跌宕起伏，人物形象栩栩如生，出版后不久便登上了畅销书排行榜。"],"a":1,"type":"단어 안의 뜻 반복","why":"“涌现”에 이미 ‘나타나다’는 뜻이 있어 끝의 “出现”이 겹친다.","fix":"宋代是中国古代科技发展的一个高峰，这一时期涌现出了沈括、苏颂等一大批杰出科学家。","words":[["涌现","yǒngxiàn","대거 나타나다"],["沈括","Shěn Kuò","심괄(북송 과학자)"],["老龄化","lǎolínghuà","고령화"],["跌宕起伏","diē dàng qǐ fú","기복이 심하다"],["栩栩如生","xǔ xǔ rú shēng","살아 있는 듯 생생하다"]],"tr":["식물의 뿌리는 물과 양분을 흡수할 뿐 아니라 흙을 붙잡아 흙이 쓸려 내려가는 것을 효과적으로 막는다.","송대는 중국 고대 과학기술 발전의 한 정점으로, 이 시기에 심괄·소송 등 뛰어난 과학자가 대거 나왔다.","고령화가 깊어지면서 노인 돌봄 서비스 체계를 어떻게 갖출지가 사회 각계가 두루 주목하는 문제가 되었다.","이 소설은 줄거리가 굴곡이 많고 인물이 살아 있는 듯 생생해서, 출간 직후 베스트셀러 순위에 올랐다."],"ow":[[["根系","gēnxì","뿌리"],["养分","yǎngfèn","양분"],["水土流失","shuǐtǔ liúshī","토양 유실"]],[["涌现","yǒngxiàn","대거 나타나다"],["沈括","Shěn Kuò","심괄"],["苏颂","Sū Sòng","소송"],["杰出","jiéchū","뛰어나다"]],[["老龄化","lǎolínghuà","고령화"],["完善","wánshàn","완비하다"],["焦点","jiāodiǎn","초점"]],[["跌宕起伏","diē dàng qǐ fú","기복이 심하다"],["栩栩如生","xǔ xǔ rú shēng","생생하다"],["畅销书","chàngxiāoshū","베스트셀러"]]]},{"o":["唐三彩是一种盛行于唐代的低温釉陶器，因常以黄、绿、白三色为主而得名。","北极熊的毛并非白色，而是透明中空的，阳光照射后经过散射，看上去才呈现出白色。","这项调查显示，超过六成的受访者每天使用手机的时间在四小时以上。","专家指出，一些家长对孩子的生活照顾得过于太周到，反而在无形中削弱了孩子独立解决问题的能力。"],"a":3,"type":"단어 안의 뜻 반복","why":"“过于”와 “太”가 둘 다 ‘지나치게’라는 뜻이라 겹친다.","fix":"专家指出，一些家长对孩子的生活照顾得过于周到，反而在无形中削弱了孩子独立解决问题的能力。","words":[["唐三彩","tángsāncǎi","당삼채"],["釉","yòu","유약"],["散射","sǎnshè","산란하다"],["受访者","shòufǎngzhě","응답자"],["无形中","wúxíngzhōng","모르는 사이에"]],"tr":["당삼채는 당대에 유행한 저온 유약 도기로, 주로 노랑·초록·흰색 세 가지 색을 써서 그런 이름이 붙었다.","북극곰의 털은 흰색이 아니라 투명하고 속이 비어 있으며, 햇빛이 비쳐 산란되면서 흰색으로 보이는 것이다.","이번 조사에서 응답자의 60% 넘게 하루 휴대폰 사용 시간이 네 시간 이상인 것으로 나타났다.","전문가들은 일부 부모가 아이의 생활을 지나치게 세심하게 챙겨 주는 바람에 오히려 아이가 스스로 문제를 해결하는 능력을 모르는 사이에 약하게 만든다고 지적한다."],"ow":[[["唐三彩","tángsāncǎi","당삼채"],["盛行","shèngxíng","유행하다"],["釉","yòu","유약"]],[["北极熊","běijíxióng","북극곰"],["中空","zhōngkōng","속이 비다"],["散射","sǎnshè","산란하다"]],[["受访者","shòufǎngzhě","응답자"],["六成","liù chéng","60%"]],[["过于","guòyú","지나치게"],["无形中","wúxíngzhōng","모르는 사이에"],["削弱","xuēruò","약화시키다"]]]},{"o":["张衡是东汉时期杰出的天文学家，他发明的地动仪，它能够测知数百里外发生地震的方向。","银杏早在两亿多年前就已出现在地球上，是现存最古老的种子植物之一，因此被称为植物界的“活化石”。","人们之所以容易对短视频上瘾，在很大程度上是因为大脑会不断从中获得即时的满足感。","这家老字号药店始创于清朝康熙年间，三百多年来始终秉承“炮制虽繁必不敢省人工”的祖训。"],"a":0,"type":"기타 군더더기(주어 반복)","why":"주어 “他发明的地动仪” 뒤에 “它”를 또 써서 주어가 두 번 나온다.","fix":"张衡是东汉时期杰出的天文学家，他发明的地动仪能够测知数百里外发生地震的方向。","words":[["张衡","Zhāng Héng","장형(동한 천문학자)"],["地动仪","dìdòngyí","지동의(지진계)"],["银杏","yínxìng","은행나무"],["上瘾","shàngyǐn","중독되다"],["老字号","lǎozìhao","오래된 유명 상호"],["秉承","bǐngchéng","이어받다"]],"tr":["장형은 동한 시기의 뛰어난 천문학자로, 그가 발명한 지동의는 수백 리 밖에서 일어난 지진의 방향을 알아낼 수 있었다.","은행나무는 이미 2억여 년 전에 지구에 나타났으며 현존하는 가장 오래된 종자식물 중 하나여서 식물계의 ‘살아 있는 화석’이라 불린다.","사람들이 짧은 동영상에 쉽게 빠지는 것은 대체로 뇌가 그 안에서 즉각적인 만족감을 계속 얻기 때문이다.","이 오래된 약방은 청나라 강희 연간에 문을 열었고, 300여 년 동안 ‘약재 가공이 번거로워도 결코 손품을 아끼지 않는다’는 가훈을 지켜 왔다."],"ow":[[["张衡","Zhāng Héng","장형"],["东汉","Dōng Hàn","동한"],["地动仪","dìdòngyí","지동의(지진계)"]],[["银杏","yínxìng","은행나무"],["种子植物","zhǒngzi zhíwù","종자식물"],["活化石","huóhuàshí","살아 있는 화석"]],[["上瘾","shàngyǐn","중독되다"],["即时","jíshí","즉각적인"],["满足感","mǎnzúgǎn","만족감"]],[["老字号","lǎozìhao","오래된 유명 상호"],["康熙","Kāngxī","강희(청 연호)"],["秉承","bǐngchéng","이어받다"],["炮制","páozhì","약재를 가공하다"],["祖训","zǔxùn","가훈"]]]},{"o":["太极拳动作舒缓、刚柔相济，长期练习能够增强体质，对调节身心也大有裨益。","二维码技术虽然诞生于日本，却在中国得到了最为广泛的应用，深刻改变了人们的支付习惯。","这位年过八旬的老教授坚持亲自自己动手整理祖父留下的数千封书信，并逐一标注写作年代。","火山喷发虽然会带来巨大的灾难，但喷出的火山灰经过长期风化，却能形成十分肥沃的土壤。"],"a":2,"type":"기타 군더더기","why":"“亲自”와 “自己”가 같은 뜻이라 하나가 군더더기다.","fix":"这位年过八旬的老教授坚持亲自动手整理祖父留下的数千封书信，并逐一标注写作年代。","words":[["刚柔相济","gāng róu xiāng jì","강함과 부드러움이 어우러지다"],["裨益","bìyì","도움, 이익"],["年过八旬","nián guò bā xún","나이가 여든을 넘다"],["标注","biāozhù","표기하다"],["风化","fēnghuà","풍화하다"],["肥沃","féiwò","비옥하다"]],"tr":["태극권은 동작이 느긋하고 강함과 부드러움이 어우러져, 오래 수련하면 체질을 튼튼히 하고 몸과 마음을 다스리는 데도 큰 도움이 된다.","QR코드 기술은 일본에서 태어났지만 중국에서 가장 널리 쓰이며 사람들의 결제 습관을 크게 바꿔 놓았다.","여든이 넘은 이 노교수는 할아버지가 남긴 수천 통의 편지를 직접 손수 정리하면서 하나하나 쓴 시기를 적어 넣고 있다.","화산 폭발은 큰 재난을 가져오지만, 뿜어져 나온 화산재는 오랜 풍화를 거쳐 매우 비옥한 흙이 된다."],"ow":[[["太极拳","tàijíquán","태극권"],["舒缓","shūhuǎn","느긋하다"],["刚柔相济","gāng róu xiāng jì","강함과 부드러움이 어우러지다"],["裨益","bìyì","도움"]],[["二维码","èrwéimǎ","QR코드"],["诞生","dànshēng","태어나다"],["支付","zhīfù","결제"]],[["年过八旬","nián guò bā xún","여든이 넘다"],["书信","shūxìn","편지"],["逐一","zhúyī","하나하나"],["标注","biāozhù","표기하다"]],[["喷发","pēnfā","분출하다"],["火山灰","huǒshānhuī","화산재"],["风化","fēnghuà","풍화"],["肥沃","féiwò","비옥하다"]]]},{"o":["黄河携带的泥沙量居世界大河之首，下游河床不断淤积抬高，形成了举世闻名的“地上河”。","剪纸是中国最古老的民间艺术之一，人们常在春节时把寓意吉祥的窗花贴在窗户上。","与传统燃油车相比，电动汽车在行驶过程中几乎不排放尾气，但其电池回收问题仍有待解决。","在繁忙的工作之余以外，她还坚持钻研古琴演奏，多次在全国性比赛中获奖。"],"a":3,"type":"기타 군더더기","why":"“之余”에 이미 ‘~외에’라는 뜻이 있어 “以外”가 겹친다.","fix":"在繁忙的工作之余，她还坚持钻研古琴演奏，多次在全国性比赛中获奖。","words":[["淤积","yūjī","(흙이) 쌓이다"],["举世闻名","jǔ shì wén míng","세상에 널리 알려지다"],["窗花","chuānghuā","창문 장식 종이 오리기"],["尾气","wěiqì","배기가스"],["钻研","zuānyán","깊이 연구하다"],["古琴","gǔqín","고금(현악기)"]],"tr":["황하가 실어 나르는 진흙과 모래의 양은 세계 큰 강 가운데 으뜸이어서, 하류 강바닥이 계속 쌓여 높아지며 세상에 이름난 ‘땅 위의 강’이 되었다.","종이 오리기는 중국에서 가장 오래된 민간 예술 가운데 하나로, 사람들은 춘절에 길한 뜻을 담은 창문 장식을 창에 붙이곤 한다.","기존 연료 자동차에 비해 전기차는 달릴 때 배기가스를 거의 내뿜지 않지만, 배터리 회수 문제는 아직 해결되지 않았다.","바쁜 업무 틈틈이 그녀는 고금 연주를 꾸준히 갈고닦아 전국 대회에서 여러 차례 상을 받았다."],"ow":[[["泥沙","níshā","진흙과 모래"],["河床","héchuáng","강바닥"],["淤积","yūjī","쌓이다"],["举世闻名","jǔ shì wén míng","세상에 널리 알려지다"]],[["剪纸","jiǎnzhǐ","종이 오리기"],["寓意","yùyì","뜻을 담다"],["吉祥","jíxiáng","길하다"],["窗花","chuānghuā","창문 장식"]],[["燃油车","rányóuchē","연료 자동차"],["尾气","wěiqì","배기가스"],["回收","huíshōu","회수하다"]],[["之余","zhī yú","~하는 틈에"],["钻研","zuānyán","깊이 연구하다"],["古琴","gǔqín","고금"]]]},{"o":["天坛是明清两代皇帝祭天、祈求五谷丰登的场所，其建筑布局处处体现着“天圆地方”的观念。","凡是读过《红楼梦》的人，都无不为书中人物命运的起落沉浮而感慨万千。","研究发现，经常与他人进行面对面交流的老年人，患阿尔茨海默病的风险相对较低。","这座城市的地铁线路纵横交错，四通八达，极大地方便了市民的日常出行。"],"a":1,"type":"기타 군더더기","why":"“无不”가 이미 ‘모두 ~하다’는 뜻인데 앞에 “都”를 또 써서 겹친다.","fix":"凡是读过《红楼梦》的人，无不为书中人物命运的起落沉浮而感慨万千。","words":[["五谷丰登","wǔ gǔ fēng dēng","오곡이 풍성하다"],["红楼梦","Hónglóu Mèng","홍루몽"],["沉浮","chénfú","흥망성쇠"],["感慨万千","gǎn kǎi wàn qiān","감회가 무량하다"],["阿尔茨海默病","Ā'ěrcíhǎimò bìng","알츠하이머병"],["纵横交错","zòng héng jiāo cuò","종횡으로 얽히다"]],"tr":["천단은 명청 두 왕조의 황제가 하늘에 제사 지내며 풍년을 빌던 곳으로, 건물 배치 곳곳에 ‘하늘은 둥글고 땅은 네모나다’는 관념이 드러나 있다.","《홍루몽》을 읽은 사람이라면 누구나 책 속 인물들의 기구한 운명에 깊은 감회를 느낀다.","연구에 따르면 다른 사람과 자주 얼굴을 맞대고 이야기하는 노인은 알츠하이머병에 걸릴 위험이 비교적 낮다.","이 도시의 지하철 노선은 종횡으로 얽혀 사방으로 통하므로 시민들의 일상 이동이 매우 편리해졌다."],"ow":[[["天坛","Tiāntán","천단"],["祈求","qíqiú","빌다"],["五谷丰登","wǔ gǔ fēng dēng","오곡이 풍성하다"],["天圆地方","tiān yuán dì fāng","하늘은 둥글고 땅은 네모나다"]],[["凡是","fánshì","무릇"],["红楼梦","Hónglóu Mèng","홍루몽"],["沉浮","chénfú","흥망성쇠"],["感慨万千","gǎn kǎi wàn qiān","감회가 무량하다"]],[["面对面","miàn duì miàn","얼굴을 맞대고"],["阿尔茨海默病","Ā'ěrcíhǎimò bìng","알츠하이머병"]],[["纵横交错","zòng héng jiāo cuò","종횡으로 얽히다"],["四通八达","sì tōng bā dá","사방으로 통하다"],["出行","chūxíng","외출하다"]]]}],[{"o":["孔子主张“有教无类”，打破了贵族对教育的垄断，使平民子弟也有了接受教育的机会。","冰川是地球上最大的淡水资源库，一旦大面积消融，不仅会导致海平面上升，还会危及众多下游地区的水源供给。","这款应用程序会根据用户的阅读习惯，自动推荐其可能感兴趣的文章和书籍。","近年来，当地通过引进先进设备和培训技术人员，大幅增强了传统丝绸的生产水平。"],"a":3,"type":"동사–목적어","why":"“增强”은 “水平”과 어울리지 않는다. 수준은 “提高”한다.","fix":"近年来，当地通过引进先进设备和培训技术人员，大幅提高了传统丝绸的生产水平。","words":[["有教无类","yǒu jiào wú lèi","가르침에 차별을 두지 않다"],["垄断","lǒngduàn","독점하다"],["消融","xiāoróng","녹아 없어지다"],["危及","wēijí","위협하다"],["丝绸","sīchóu","비단"]],"tr":["공자는 ‘가르침에 차별을 두지 않는다’고 주장해 귀족의 교육 독점을 깨뜨렸고, 평민 자녀도 교육을 받을 기회를 얻게 했다.","빙하는 지구에서 가장 큰 담수 저장고로, 넓은 면적이 녹으면 해수면이 올라갈 뿐 아니라 많은 하류 지역의 물 공급도 위협받는다.","이 앱은 사용자의 독서 습관에 따라 관심을 가질 만한 글과 책을 자동으로 추천해 준다.","최근 몇 년 동안 이 지역은 선진 설비를 들여오고 기술자를 교육해 전통 비단의 생산 수준을 크게 끌어올렸다."],"ow":[[["有教无类","yǒu jiào wú lèi","가르침에 차별을 두지 않다"],["贵族","guìzú","귀족"],["垄断","lǒngduàn","독점"],["子弟","zǐdì","자녀"]],[["冰川","bīngchuān","빙하"],["消融","xiāoróng","녹아 없어지다"],["危及","wēijí","위협하다"],["供给","gōngjǐ","공급"]],[["应用程序","yìngyòng chéngxù","앱"],["推荐","tuījiàn","추천하다"]],[["引进","yǐnjìn","들여오다"],["培训","péixùn","교육하다"],["丝绸","sīchóu","비단"]]]},{"o":["编钟是中国古代重要的打击乐器，1978年出土的曾侯乙编钟至今仍能演奏出完整的乐曲。","为了满足日益增长的游客数量，平遥古城景区今年新开辟了三条特色步行游览路线。","人们在情绪低落时往往更倾向于选择高热量食物，这在一定程度上是大脑寻求安慰的本能反应。","由于海拔高、空气稀薄，初到青藏高原的人常会出现头痛、胸闷等高原反应。"],"a":1,"type":"동사–목적어","why":"“满足”의 목적어로 “数量”은 맞지 않는다. 채우는 것은 “需求”다.","fix":"为了满足日益增长的游客需求，平遥古城景区今年新开辟了三条特色步行游览路线。","words":[["编钟","biānzhōng","편종"],["曾侯乙","Zēng hóu Yǐ","증후을(전국시대 제후)"],["开辟","kāipì","개척하다, 새로 열다"],["倾向","qīngxiàng","경향, 기울다"],["稀薄","xībó","희박하다"]],"tr":["편종은 중국 고대의 중요한 타악기로, 1978년에 출토된 증후을 편종은 지금도 완전한 곡을 연주할 수 있다.","날로 늘어나는 관광객의 수요를 맞추려고 평요 고성 관광지는 올해 특색 있는 도보 관광 코스 세 개를 새로 열었다.","사람은 기분이 가라앉을 때 고열량 음식을 고르는 경향이 있는데, 이는 어느 정도 뇌가 위안을 찾는 본능적인 반응이다.","해발이 높고 공기가 희박해서 칭짱고원에 처음 간 사람은 흔히 두통, 가슴 답답함 같은 고산 반응을 겪는다."],"ow":[[["编钟","biānzhōng","편종"],["打击乐器","dǎjī yuèqì","타악기"],["曾侯乙","Zēng hóu Yǐ","증후을"]],[["平遥古城","Píngyáo Gǔchéng","평요 고성"],["开辟","kāipì","새로 열다"]],[["低落","dīluò","가라앉다"],["倾向","qīngxiàng","경향이 있다"],["本能","běnnéng","본능"]],[["海拔","hǎibá","해발"],["稀薄","xībó","희박하다"],["胸闷","xiōngmèn","가슴이 답답하다"],["青藏高原","Qīng-Zàng Gāoyuán","칭짱고원"]]]},{"o":["秦始皇统一六国后，下令统一文字、货币和度量衡，开创了此后两千多年中央集权政治制度的基础。","适度运动能够促进大脑分泌内啡肽，让人产生愉悦感，因此被视为缓解抑郁情绪的有效方式之一。","这家书店不仅出售图书，还定期举办读书会和作家讲座，逐渐成为城市里的一处文化地标。","沙漠中的仙人掌叶子退化成了针状，这样可以最大限度地减少水分蒸发。"],"a":0,"type":"동사–목적어","why":"开创은 局面·先河 같은 말과 어울리고, 基础(기초)와는 어울리지 않는다. 基础는 奠定과 짝을 이룬다.","fix":"秦始皇统一六国后，下令统一文字、货币和度量衡，奠定了此后两千多年中央集权政治制度的基础。","words":[["度量衡","dùliànghéng","도량형"],["中央集权","zhōngyāng jíquán","중앙집권"],["内啡肽","nèifēitài","엔도르핀"],["抑郁","yìyù","우울하다"],["仙人掌","xiānrénzhǎng","선인장"],["开创","kāichuàng","처음으로 열다, 개척하다"]],"tr":["진시황은 여섯 나라를 통일한 뒤 문자·화폐·도량형을 통일하라고 명해, 이후 2천여 년 중앙집권 정치 제도의 기틀을 닦았다.","적당한 운동은 뇌에서 엔도르핀 분비를 촉진해 즐거움을 느끼게 하므로, 우울한 기분을 푸는 효과적인 방법 중 하나로 여겨진다.","이 서점은 책을 팔 뿐 아니라 독서 모임과 작가 강연을 정기적으로 열어 도시의 문화 명소가 되어 가고 있다.","사막의 선인장은 잎이 가시 모양으로 퇴화해서 수분 증발을 최대한 줄일 수 있다."],"ow":[[["秦始皇","Qín Shǐhuáng","진시황"],["度量衡","dùliànghéng","도량형"],["中央集权","zhōngyāng jíquán","중앙집권"],["开创","kāichuàng","열다"]],[["分泌","fēnmì","분비하다"],["内啡肽","nèifēitài","엔도르핀"],["愉悦","yúyuè","즐겁다"],["抑郁","yìyù","우울하다"]],[["定期","dìngqī","정기적으로"],["讲座","jiǎngzuò","강좌"],["地标","dìbiāo","랜드마크"]],[["仙人掌","xiānrénzhǎng","선인장"],["退化","tuìhuà","퇴화하다"],["蒸发","zhēngfā","증발"]]]},{"o":["古代驿站负责传递官府文书、接待往来官员，是维系中央与地方联系的重要纽带。","这位导演的新作打破了以往的叙事模式，在国际电影节上一举斩获了多项大奖。","钱塘江大潮的潮头最高可达数米，声势如万马奔腾，每年中秋前后，观潮的人数从各地蜂拥而至。","长期处于噪音环境中，不仅会损伤听力，还可能引起失眠、烦躁等一系列身心问题。"],"a":2,"type":"주어–술어","why":"“人数”(숫자)는 “蜂拥而至”(몰려오다)할 수 없다. 몰려오는 것은 사람이다.","fix":"钱塘江大潮的潮头最高可达数米，声势如万马奔腾，每年中秋前后，观潮的人们从各地蜂拥而至。","words":[["驿站","yìzhàn","역참"],["纽带","niǔdài","유대, 연결 고리"],["斩获","zhǎnhuò","(상을) 거머쥐다"],["万马奔腾","wàn mǎ bēn téng","만 마리 말이 내달리듯 기세 좋다"],["蜂拥而至","fēng yōng ér zhì","벌떼처럼 몰려들다"],["烦躁","fánzào","초조하다"]],"tr":["옛 역참은 관청 문서를 전하고 오가는 관리를 접대하는 일을 맡아, 중앙과 지방을 이어 주는 중요한 고리였다.","이 감독의 신작은 기존의 서사 방식을 깨고 국제 영화제에서 단번에 여러 개의 큰 상을 거머쥐었다.","첸탕강 대조수의 물머리는 최고 몇 미터에 이르고 기세가 만 마리 말이 내달리는 듯해, 해마다 중추절 무렵이면 조수를 보려는 사람들이 각지에서 몰려든다.","오랫동안 소음 속에 있으면 청력이 손상될 뿐 아니라 불면, 초조함 등 여러 몸과 마음의 문제가 생길 수 있다."],"ow":[[["驿站","yìzhàn","역참"],["官府","guānfǔ","관청"],["维系","wéixì","유지하다"],["纽带","niǔdài","연결 고리"]],[["叙事","xùshì","서사"],["一举","yìjǔ","단번에"],["斩获","zhǎnhuò","거머쥐다"]],[["钱塘江","Qiántáng Jiāng","첸탕강"],["万马奔腾","wàn mǎ bēn téng","만 마리 말이 내달리듯"],["蜂拥而至","fēng yōng ér zhì","벌떼처럼 몰려들다"]],[["噪音","zàoyīn","소음"],["损伤","sǔnshāng","손상시키다"],["烦躁","fánzào","초조하다"]]]},{"o":["吐鲁番盆地地势低洼，夏季的气温异常炎热，当地人便利用坎儿井将地下水引来灌溉农田。","汉字经历了从甲骨文、金文到小篆、隶书、楷书的漫长演变，字形逐渐由繁趋简。","不少城市开始在老旧小区加装电梯，以解决老年居民上下楼困难的问题。","据气象部门预测，受冷空气影响，本周后期北方大部分地区将出现大风降温天气。"],"a":0,"type":"주어–술어","why":"“气温”은 “高”와 어울리고 “炎热”는 “天气”와 어울린다.","fix":"吐鲁番盆地地势低洼，夏季的天气异常炎热，当地人便利用坎儿井将地下水引来灌溉农田。","words":[["吐鲁番","Tǔlǔfān","투루판"],["低洼","dīwā","움푹 낮다"],["坎儿井","kǎnrjǐng","카레즈(지하 수로)"],["小篆","xiǎozhuàn","소전(서체)"],["隶书","lìshū","예서"],["由繁趋简","yóu fán qū jiǎn","복잡함에서 간단함으로 가다"]],"tr":["투루판 분지는 지대가 낮고 여름 날씨가 몹시 무더워서, 현지 사람들은 카레즈로 지하수를 끌어와 농지에 물을 댄다.","한자는 갑골문·금문에서 소전·예서·해서에 이르는 긴 변화를 거치며 글자꼴이 점점 복잡함에서 간단함으로 바뀌었다.","적지 않은 도시가 오래된 단지에 엘리베이터를 설치해 노인 주민이 계단을 오르내리기 힘든 문제를 해결하기 시작했다.","기상 당국의 예보에 따르면 찬 공기의 영향으로 이번 주 후반 북방 대부분 지역에 강풍과 함께 기온이 내려가겠다."],"ow":[[["吐鲁番","Tǔlǔfān","투루판"],["盆地","péndì","분지"],["低洼","dīwā","움푹 낮다"],["坎儿井","kǎnrjǐng","카레즈(지하 수로)"]],[["甲骨文","jiǎgǔwén","갑골문"],["小篆","xiǎozhuàn","소전"],["隶书","lìshū","예서"],["楷书","kǎishū","해서"],["由繁趋简","yóu fán qū jiǎn","복잡함에서 간단함으로"]],[["小区","xiǎoqū","주거 단지"],["加装","jiāzhuāng","추가 설치하다"]],[["气象","qìxiàng","기상"],["预测","yùcè","예측하다"],["降温","jiàngwēn","기온이 내려가다"]]]},{"o":["啄木鸟每天要啄树数千次，其头部特殊的骨骼结构能够有效缓冲撞击带来的震动。","在信息爆炸的时代，比获取信息更重要的，是辨别信息真伪的能力。","端午节是我国历史最悠久的传统节日之一，而赛龙舟是这一天最具代表性的时节。","这座跨海大桥全长五十多公里，建成后，两岸之间的通行时间由原来的三个多小时缩短至半小时左右。"],"a":2,"type":"주어–목적어","why":"“赛龙舟是……时节”에서 행사인 ‘용선 경주’를 ‘시기’라고 해 주어와 목적어가 맞지 않는다.","fix":"端午节是我国历史最悠久的传统节日之一，而赛龙舟是这一天最具代表性的活动。","words":[["啄木鸟","zhuómùniǎo","딱따구리"],["骨骼","gǔgé","골격"],["缓冲","huǎnchōng","완충하다"],["真伪","zhēnwěi","진위"],["龙舟","lóngzhōu","용선"]],"tr":["딱따구리는 하루에 수천 번 나무를 쪼는데, 머리의 특수한 골격 구조가 부딪힐 때의 진동을 효과적으로 완충해 준다.","정보가 폭발하는 시대에는 정보를 얻는 것보다 정보의 진위를 가려내는 능력이 더 중요하다.","단오절은 우리나라에서 역사가 가장 오래된 전통 명절 가운데 하나이며, 용선 경주는 이날 가장 대표적인 행사다.","이 바다를 건너는 대교는 전체 길이가 50여 킬로미터로, 개통 뒤 양안을 오가는 시간이 세 시간 남짓에서 30분 정도로 줄었다."],"ow":[[["啄木鸟","zhuómùniǎo","딱따구리"],["骨骼","gǔgé","골격"],["缓冲","huǎnchōng","완충하다"],["撞击","zhuàngjī","부딪히다"]],[["爆炸","bàozhà","폭발하다"],["辨别","biànbié","가려내다"],["真伪","zhēnwěi","진위"]],[["悠久","yōujiǔ","유구하다"],["赛龙舟","sài lóngzhōu","용선 경주"],["时节","shíjié","시기"]],[["跨海大桥","kuàhǎi dàqiáo","해상 대교"],["缩短","suōduǎn","단축하다"]]]},{"o":["酸雨会腐蚀建筑物和文物古迹，还会使土壤酸化，导致农作物减产。","徐霞客游历大半个中国、历时三十余年写成的《徐霞客游记》，是明代一位杰出的地理学家。","他虽然年近七旬，却仍坚持每天阅读外文文献，及时跟进本领域的最新研究进展。","一些动物在冬眠期间体温会大幅下降，心跳和呼吸也随之变得极其缓慢。"],"a":1,"type":"주어–목적어","why":"주어는 책 “《徐霞客游记》”인데 목적어가 사람 “地理学家”라 “A是B”가 맞지 않는다.","fix":"徐霞客游历大半个中国、历时三十余年写成的《徐霞客游记》，是明代一部杰出的地理学著作。","words":[["腐蚀","fǔshí","부식시키다"],["徐霞客","Xú Xiákè","서하객(명대 여행가)"],["游历","yóulì","두루 돌아다니다"],["文献","wénxiàn","문헌"],["冬眠","dōngmián","겨울잠"]],"tr":["산성비는 건물과 문화재를 부식시키고 토양을 산성으로 만들어 농작물 수확을 줄인다.","서하객이 중국 대부분을 돌아다니며 30여 년에 걸쳐 쓴 《서하객유기》는 명대의 뛰어난 지리학 저작이다.","그는 일흔이 가까운 나이에도 매일 외국어 문헌을 읽으며 자기 분야의 최신 연구 동향을 놓치지 않고 따라간다.","어떤 동물은 겨울잠을 자는 동안 체온이 크게 떨어지고 심장 박동과 호흡도 그에 따라 매우 느려진다."],"ow":[[["酸雨","suānyǔ","산성비"],["腐蚀","fǔshí","부식시키다"],["古迹","gǔjì","고적"],["减产","jiǎnchǎn","감산"]],[["徐霞客","Xú Xiákè","서하객"],["游历","yóulì","두루 돌아다니다"],["地理学家","dìlǐxuéjiā","지리학자"]],[["年近七旬","nián jìn qī xún","일흔이 가깝다"],["文献","wénxiàn","문헌"],["跟进","gēnjìn","따라가다"]],[["冬眠","dōngmián","겨울잠"],["心跳","xīntiào","심장 박동"],["随之","suízhī","그에 따라"]]]},{"o":["嘉峪关位于河西走廊中部，是明长城西端的起点，素有“天下第一雄关”之称。","合理规划时间并不意味着把日程排得满满当当，而是要在忙碌与休息之间找到平衡。","鲸虽然生活在海里，却不是鱼类，而是用肺呼吸的哺乳动物。","能否坚持实地调查、掌握第一手资料，是一部地方志编撰成功的重要保证。"],"a":3,"type":"양면–한면","why":"能否(할 수도 못 할 수도)는 양쪽을 말하는데, 重要保证(성공을 보장함)은 한쪽만 말해 앞뒤가 맞지 않는다.","fix":"坚持实地调查、掌握第一手资料，是一部地方志编撰成功的重要保证。","words":[["嘉峪关","Jiāyù Guān","가욕관"],["河西走廊","Héxī Zǒuláng","하서회랑"],["雄关","xióngguān","웅장한 관문"],["哺乳动物","bǔrǔ dòngwù","포유동물"],["地方志","dìfāngzhì","지방지"],["编撰","biānzhuàn","편찬하다"]],"tr":["가욕관은 하서회랑 중부에 있는 명나라 장성 서쪽 끝의 출발점으로, 예로부터 ‘천하제일웅관’이라 불렸다.","시간을 잘 짠다는 것은 일정을 빽빽하게 채운다는 뜻이 아니라, 바쁨과 휴식 사이에서 균형을 찾는다는 뜻이다.","고래는 바다에 살지만 물고기가 아니라 폐로 숨을 쉬는 포유동물이다.","현장 조사를 꾸준히 하고 직접 얻은 자료를 확보하는 것이 지방지 편찬을 성공으로 이끄는 중요한 보증이다."],"ow":[[["嘉峪关","Jiāyù Guān","가욕관"],["河西走廊","Héxī Zǒuláng","하서회랑"],["雄关","xióngguān","웅장한 관문"],["素有","sùyǒu","예로부터 ~이 있다"]],[["规划","guīhuà","계획하다"],["意味着","yìwèizhe","의미하다"],["满满当当","mǎnmǎn dāngdāng","빽빽하다"]],[["鲸","jīng","고래"],["哺乳动物","bǔrǔ dòngwù","포유동물"]],[["实地","shídì","현장"],["第一手资料","dìyīshǒu zīliào","직접 얻은 자료"],["地方志","dìfāngzhì","지방지"],["编撰","biānzhuàn","편찬하다"]]]},{"o":["能否严格把控采摘时间与炒制火候，是西湖龙井茶品质上乘的根本保证。","这座城市的公共图书馆实行二十四小时自助借还，深受附近居民和上班族的欢迎。","气候变暖导致北极海冰面积逐年缩小，北极熊的生存空间也受到了严重威胁。","尽管面临资金短缺和人才流失的双重困境，这家初创企业仍然坚持自主研发。"],"a":0,"type":"양면–한면","why":"“能否”(두 면)과 “品质上乘”(한 면)이 맞지 않는다.","fix":"严格把控采摘时间与炒制火候，是西湖龙井茶品质上乘的根本保证。","words":[["把控","bǎkòng","관리하다, 통제하다"],["火候","huǒhou","불 조절"],["龙井茶","lóngjǐngchá","룽징차"],["上乘","shàngchéng","최상급"],["困境","kùnjìng","곤경"],["初创","chūchuàng","막 창업한"]],"tr":["찻잎 따는 시기와 덖는 불 조절을 엄격하게 지키는 것이 시후 룽징차가 최상급 품질을 갖추는 근본 보증이다.","이 도시의 공공 도서관은 24시간 무인 대출·반납을 운영해 주변 주민과 직장인에게 큰 인기를 얻고 있다.","기후 온난화로 북극 해빙 면적이 해마다 줄어들어 북극곰의 생존 공간도 심각한 위협을 받고 있다.","자금 부족과 인재 유출이라는 이중고를 겪으면서도 이 신생 기업은 여전히 자체 연구 개발을 고집하고 있다."],"ow":[[["把控","bǎkòng","관리하다"],["采摘","cǎizhāi","따다"],["火候","huǒhou","불 조절"],["龙井茶","lóngjǐngchá","룽징차"],["上乘","shàngchéng","최상급"]],[["自助","zìzhù","셀프"],["借还","jièhuán","대출과 반납"]],[["海冰","hǎibīng","해빙(바다 얼음)"],["逐年","zhúnián","해마다"],["威胁","wēixié","위협"]],[["短缺","duǎnquē","부족"],["流失","liúshī","유출되다"],["困境","kùnjìng","곤경"],["初创","chūchuàng","막 창업한"]]]},{"o":["由于缺乏有效的监管，部分地区的地下水被过度开采，导致地面沉降现象时有发生。","唐代诗人杜甫一生忧国忧民，他的诗真实反映了安史之乱前后的社会面貌，因此被称为“诗史”。","在这场民俗晚会上，观众们听到了悠扬的侗族大歌和绚丽多姿的苗族舞蹈。","研究发现，婴儿在出生后的头几个月里，就已经能够分辨母亲的声音和气味。"],"a":2,"type":"목적어 여럿 중 일부","why":"“听到”는 “侗族大歌”와는 맞지만 “苗族舞蹈”(춤)와는 맞지 않는다. 춤은 “看到”한다.","fix":"在这场民俗晚会上，观众们听到了悠扬的侗族大歌，看到了绚丽多姿的苗族舞蹈。","words":[["沉降","chénjiàng","침하하다"],["忧国忧民","yōu guó yōu mín","나라와 백성을 걱정하다"],["安史之乱","Ān Shǐ zhī luàn","안사의 난"],["悠扬","yōuyáng","(소리가) 은은하게 울려 퍼지다"],["侗族","Dòngzú","둥족"],["绚丽多姿","xuàn lì duō zī","화려하고 다채롭다"]],"tr":["효과적인 관리 감독이 없어 일부 지역의 지하수가 지나치게 뽑혀 나가면서 지반 침하가 종종 일어난다.","당대 시인 두보는 평생 나라와 백성을 걱정했고, 그의 시는 안사의 난 전후의 사회 모습을 사실대로 담아 ‘시로 쓴 역사’라 불린다.","이 민속 공연에서 관객들은 은은하게 울려 퍼지는 둥족 대가와 화려하고 다채로운 먀오족 춤을 감상했다.","연구에 따르면 아기는 태어난 지 몇 달 만에 이미 엄마의 목소리와 냄새를 구별할 수 있다."],"ow":[[["监管","jiānguǎn","관리 감독"],["开采","kāicǎi","채굴하다"],["沉降","chénjiàng","침하하다"]],[["杜甫","Dù Fǔ","두보"],["忧国忧民","yōu guó yōu mín","나라와 백성을 걱정하다"],["安史之乱","Ān Shǐ zhī luàn","안사의 난"],["诗史","shīshǐ","시로 쓴 역사"]],[["民俗","mínsú","민속"],["悠扬","yōuyáng","은은하게 울려 퍼지다"],["侗族","Dòngzú","둥족"],["绚丽多姿","xuàn lì duō zī","화려하고 다채롭다"]],[["婴儿","yīng'ér","아기"],["分辨","fēnbiàn","구별하다"],["气味","qìwèi","냄새"]]]}],[{"o":["由于连日阴雨，工匠们把这批刚上完漆的木雕没能及时晾干，只好推迟交付。","安徽宏村依山而建，粉墙黛瓦的徽派民居与湖光山色相映成趣，被誉为“中国画里的乡村”。","心理学研究表明，人们在做出重大决定时，往往会不自觉地高估自己判断的准确性。","由于城市热岛效应，市中心的气温常常比郊区高出两三摄氏度。"],"a":0,"type":"부사·능원동사·부정사 위치","why":"부정어 “没能”은 “把” 앞에 와야 한다. “把……没能晾干”은 어순이 틀렸다.","fix":"由于连日阴雨，工匠们没能把这批刚上完漆的木雕及时晾干，只好推迟交付。","words":[["晾干","liànggān","말리다"],["交付","jiāofù","납품하다"],["粉墙黛瓦","fěn qiáng dài wǎ","흰 벽과 검은 기와"],["相映成趣","xiāng yìng chéng qù","서로 어우러져 운치가 있다"],["高估","gāogū","과대평가하다"]],"tr":["며칠째 흐리고 비가 와서 장인들은 막 옻칠을 마친 목각품을 제때 말리지 못해 납품을 미룰 수밖에 없었다.","안후이성 훙춘은 산을 따라 지어져 흰 벽과 검은 기와의 휘주식 민가가 호수와 산 풍경과 어우러지며, ‘중국 그림 속 마을’로 불린다.","심리학 연구에 따르면 사람은 중대한 결정을 내릴 때 자기도 모르게 자기 판단의 정확성을 과대평가하는 경우가 많다.","도시 열섬 효과 때문에 도심 기온은 교외보다 흔히 2~3도 높다."],"ow":[[["连日","liánrì","연일"],["木雕","mùdiāo","목각"],["晾干","liànggān","말리다"],["交付","jiāofù","납품하다"]],[["宏村","Hóngcūn","훙춘"],["粉墙黛瓦","fěn qiáng dài wǎ","흰 벽과 검은 기와"],["徽派","Huīpài","휘주식"],["相映成趣","xiāng yìng chéng qù","서로 어우러져 운치 있다"]],[["不自觉","bú zìjué","자기도 모르게"],["高估","gāogū","과대평가하다"]],[["热岛效应","rèdǎo xiàoyìng","열섬 효과"],["郊区","jiāoqū","교외"],["摄氏度","shèshìdù","섭씨 도"]]]},{"o":["云南元阳梯田是哈尼族人民世代开垦的杰作，层层叠叠，蔚为壮观。","研究人员指出，经常熬夜不仅会打乱生物钟，还可能导致新陈代谢紊乱。","由于战乱频繁，这批宋代藏书家珍藏的孤本古籍被没有完整保存下来，大多已散佚。","在全球化背景下，越来越多的外国留学生选择来中国学习中医、书法等传统文化课程。"],"a":2,"type":"부사·능원동사·부정사 위치","why":"부정어 “没有”는 “被” 앞에 와야 한다. “被没有”는 어순이 틀렸다.","fix":"由于战乱频繁，这批宋代藏书家珍藏的孤本古籍没有被完整保存下来，大多已散佚。","words":[["梯田","tītián","계단식 논"],["开垦","kāikěn","개간하다"],["蔚为壮观","wèi wéi zhuàng guān","장관을 이루다"],["紊乱","wěnluàn","문란하다, 흐트러지다"],["孤本","gūběn","유일본"],["散佚","sànyì","흩어져 없어지다"]],"tr":["윈난 위안양 계단식 논은 하니족이 대대로 개간한 걸작으로, 층층이 겹겹이 이어져 장관을 이룬다.","연구진은 자주 밤을 새우면 생체 시계가 흐트러질 뿐 아니라 신진대사에 이상이 생길 수도 있다고 지적했다.","전란이 잦았던 탓에 송대 장서가들이 아끼던 이 유일본 고서들은 온전히 보존되지 못했고 대부분 흩어져 사라졌다.","세계화 속에서 점점 더 많은 외국 유학생이 중국에 와서 중의학·서예 같은 전통문화 과목을 배우는 길을 택한다."],"ow":[[["梯田","tītián","계단식 논"],["哈尼族","Hānízú","하니족"],["开垦","kāikěn","개간하다"],["蔚为壮观","wèi wéi zhuàng guān","장관을 이루다"]],[["熬夜","áoyè","밤을 새우다"],["生物钟","shēngwùzhōng","생체 시계"],["新陈代谢","xīn chén dài xiè","신진대사"],["紊乱","wěnluàn","흐트러지다"]],[["战乱","zhànluàn","전란"],["藏书家","cángshūjiā","장서가"],["孤本","gūběn","유일본"],["散佚","sànyì","흩어져 없어지다"]],[["全球化","quánqiúhuà","세계화"],["中医","zhōngyī","중의학"]]]},{"o":["极光是太阳风中的带电粒子与地球高层大气相互作用而产生的发光现象。","为了不让这门古老的技艺失传，我们把剪纸和皮影戏的制作方法应该系统地记录下来。","这家餐厅坚持使用当季的新鲜食材，虽然价格不菲，却依然天天座无虚席。","面对激烈的市场竞争，不少传统企业纷纷加快数字化转型的步伐。"],"a":1,"type":"부사·능원동사·부정사 위치","why":"능원동사 “应该”는 “把” 앞에 와야 한다.","fix":"为了不让这门古老的技艺失传，我们应该把剪纸和皮影戏的制作方法系统地记录下来。","words":[["极光","jíguāng","오로라"],["粒子","lìzǐ","입자"],["失传","shīchuán","전승이 끊기다"],["皮影戏","píyǐngxì","그림자극"],["价格不菲","jià gé bù fěi","값이 만만치 않다"],["座无虚席","zuò wú xū xí","빈자리가 없다"]],"tr":["오로라는 태양풍 속의 전하를 띤 입자가 지구 상층 대기와 작용해 생기는 발광 현상이다.","이 오래된 기예가 끊기지 않도록 우리는 종이 오리기와 그림자극의 제작 방법을 체계적으로 기록해 두어야 한다.","이 식당은 제철 신선한 재료만 고집해서, 값이 만만치 않은데도 날마다 빈자리가 없다.","치열한 시장 경쟁 앞에서 적지 않은 전통 기업이 앞다투어 디지털 전환의 속도를 높이고 있다."],"ow":[[["极光","jíguāng","오로라"],["带电粒子","dàidiàn lìzǐ","전하를 띤 입자"],["大气","dàqì","대기"]],[["失传","shīchuán","전승이 끊기다"],["剪纸","jiǎnzhǐ","종이 오리기"],["皮影戏","píyǐngxì","그림자극"]],[["食材","shícái","식재료"],["价格不菲","jià gé bù fěi","값이 만만치 않다"],["座无虚席","zuò wú xū xí","빈자리가 없다"]],[["纷纷","fēnfēn","앞다투어"],["数字化","shùzìhuà","디지털화"],["转型","zhuǎnxíng","전환하다"]]]},{"o":["古人根据月相的变化制定历法，农历的每个月便是以朔望月为基础确定的。","这款智能手表可以实时监测佩戴者的心率和睡眠质量，并及时发出健康预警。","每年春季，大批候鸟从南方飞往北方繁殖，途中需要在湿地停歇、补充体力。","为了确认这件青铜器的年代，专家们进行了细致的碳十四测定对其附着的木炭残留物。"],"a":3,"type":"개사구 위치","why":"개사구 “对其附着的木炭残留物”가 동사 뒤 끝에 붙어 있다. 동사 “进行” 앞에 와야 한다.","fix":"为了确认这件青铜器的年代，专家们对其附着的木炭残留物进行了细致的碳十四测定。","words":[["历法","lìfǎ","역법"],["朔望月","shuòwàngyuè","삭망월"],["佩戴","pèidài","착용하다"],["繁殖","fánzhí","번식하다"],["附着","fùzhuó","붙어 있다"],["残留物","cánliúwù","잔류물"]],"tr":["옛사람들은 달 모양의 변화에 따라 역법을 정했고, 음력의 한 달은 삭망월을 바탕으로 정해졌다.","이 스마트 워치는 착용자의 심박수와 수면의 질을 실시간으로 살피고 건강 경고를 제때 보내 준다.","해마다 봄이면 많은 철새가 남쪽에서 북쪽으로 날아가 번식하는데, 가는 길에 습지에서 쉬며 체력을 보충해야 한다.","이 청동기의 연대를 확인하기 위해 전문가들은 거기 붙어 있던 숯 잔여물을 대상으로 꼼꼼한 탄소14 측정을 했다."],"ow":[[["月相","yuèxiàng","달의 위상"],["历法","lìfǎ","역법"],["农历","nónglì","음력"],["朔望月","shuòwàngyuè","삭망월"]],[["监测","jiāncè","모니터링하다"],["佩戴","pèidài","착용하다"],["心率","xīnlǜ","심박수"],["预警","yùjǐng","사전 경고"]],[["候鸟","hòuniǎo","철새"],["繁殖","fánzhí","번식하다"],["湿地","shīdì","습지"],["停歇","tíngxiē","쉬다"]],[["青铜器","qīngtóngqì","청동기"],["测定","cèdìng","측정하다"],["附着","fùzhuó","붙어 있다"],["残留物","cánliúwù","잔류물"]]]},{"o":["北京烤鸭的历史可以追溯到南北朝时期，到了明清两代，它已成为宫廷宴席上的名菜。","地震发生后，救援人员争分夺秒地搜救被困群众，力争把伤亡降到最低。","这款新型材料重量仅为钢材的四分之一，强度却是钢材的数倍。","这位年过七旬的紫砂壶大师毫无保留地传授了自己几十年积累的制壶技艺给年轻的徒弟们。"],"a":3,"type":"개사구 위치","why":"“给年轻的徒弟们”이 문장 끝에 떨어져 있다. “把……传授给……”처럼 동사 바로 뒤에 붙여야 한다.","fix":"这位年过七旬的紫砂壶大师毫无保留地把自己几十年积累的制壶技艺传授给了年轻的徒弟们。","words":[["追溯","zhuīsù","거슬러 올라가다"],["宫廷","gōngtíng","궁정"],["争分夺秒","zhēng fēn duó miǎo","촌각을 다투다"],["紫砂壶","zǐshāhú","자사호(차 주전자)"],["毫无保留","háo wú bǎo liú","조금도 남김없이"]],"tr":["베이징 오리구이의 역사는 남북조 시대까지 거슬러 올라가며, 명청 두 왕조에 이르러서는 궁중 연회의 이름난 요리가 되었다.","지진이 난 뒤 구조대원들은 촌각을 다투며 갇힌 사람들을 찾아 구했고, 사상자를 최소한으로 줄이려 애썼다.","이 신소재는 무게가 강철의 4분의 1에 불과하지만 강도는 강철의 몇 배에 이른다.","일흔이 넘은 이 자사호 장인은 수십 년 동안 쌓은 주전자 제작 기술을 젊은 제자들에게 아낌없이 전수했다."],"ow":[[["烤鸭","kǎoyā","오리구이"],["追溯","zhuīsù","거슬러 올라가다"],["南北朝","Nán-Běi Cháo","남북조"],["宫廷","gōngtíng","궁정"]],[["救援","jiùyuán","구조하다"],["争分夺秒","zhēng fēn duó miǎo","촌각을 다투다"],["伤亡","shāngwáng","사상자"]],[["钢材","gāngcái","강재"],["强度","qiángdù","강도"]],[["紫砂壶","zǐshāhú","자사호"],["毫无保留","háo wú bǎo liú","조금도 남김없이"],["传授","chuánshòu","전수하다"],["徒弟","túdì","제자"]]]},{"o":["中国古代的“四书五经”是儒家思想的核心典籍，曾长期作为科举考试的主要内容。","这次被评为“非遗传承人”的，是一位技艺精湛的七十多岁的我们镇上的老木匠。","植物在光合作用中吸收二氧化碳、释放氧气，对维持大气成分的稳定起着至关重要的作用。","在快节奏的现代生活中，越来越多的人开始尝试通过冥想来缓解焦虑。"],"a":1,"type":"관형어 순서","why":"소속을 나타내는 “我们镇上的”는 관형어 맨 앞에 와야 한다.","fix":"这次被评为“非遗传承人”的，是我们镇上的一位七十多岁的技艺精湛的老木匠。","words":[["四书五经","Sìshū Wǔjīng","사서오경"],["典籍","diǎnjí","고전, 전적"],["科举","kējǔ","과거 시험"],["传承人","chuánchéngrén","전승자"],["精湛","jīngzhàn","정교하고 뛰어나다"],["冥想","míngxiǎng","명상"]],"tr":["중국 고대의 ‘사서오경’은 유가 사상의 핵심 경전으로, 오랫동안 과거 시험의 주요 내용이었다.","이번에 ‘무형문화유산 전승자’로 뽑힌 사람은 우리 동네에 사는, 솜씨가 뛰어난 일흔 남짓의 늙은 목수다.","식물은 광합성 과정에서 이산화탄소를 흡수하고 산소를 내놓아 대기 성분을 안정되게 유지하는 데 매우 중요한 역할을 한다.","빠르게 돌아가는 현대 생활 속에서 점점 더 많은 사람이 명상으로 불안을 달래려 하고 있다."],"ow":[[["四书五经","Sìshū Wǔjīng","사서오경"],["儒家","Rújiā","유가"],["典籍","diǎnjí","경전"],["科举","kējǔ","과거"]],[["传承人","chuánchéngrén","전승자"],["精湛","jīngzhàn","정교하고 뛰어나다"],["木匠","mùjiang","목수"]],[["光合作用","guānghé zuòyòng","광합성"],["二氧化碳","èryǎnghuàtàn","이산화탄소"],["至关重要","zhì guān zhòng yào","매우 중요하다"]],[["快节奏","kuài jiézòu","빠른 리듬"],["冥想","míngxiǎng","명상"],["焦虑","jiāolǜ","불안"]]]},{"o":["书架最上层摆放着几本泛黄的我祖父的清代线装古籍，至今仍保存得相当完好。","研究显示，经常食用深海鱼类有助于降低血液中的胆固醇含量。","西安城墙始建于明朝洪武年间，周长近十四公里，是中国现存最完整的古代城垣之一。","有些人在公共场合讲话时会心跳加速、手心出汗，这其实是一种正常的生理反应。"],"a":0,"type":"관형어 순서","why":"소유자 “我祖父的”가 “几本泛黄的”보다 앞에 와야 한다.","fix":"书架最上层摆放着我祖父的几本泛黄的清代线装古籍，至今仍保存得相当完好。","words":[["泛黄","fànhuáng","누렇게 바래다"],["线装","xiànzhuāng","실로 꿰맨 제본"],["胆固醇","dǎngùchún","콜레스테롤"],["城垣","chéngyuán","성벽"],["生理","shēnglǐ","생리"]],"tr":["책장 맨 위 칸에는 할아버지가 남긴 누렇게 바랜 청대 선장본 고서 몇 권이 놓여 있는데, 지금도 꽤 잘 보존되어 있다.","연구에 따르면 심해 어류를 자주 먹으면 혈중 콜레스테롤 수치를 낮추는 데 도움이 된다.","시안 성벽은 명나라 홍무 연간에 짓기 시작했으며 둘레가 14킬로미터 가까이 되는, 중국에 남아 있는 가장 온전한 옛 성벽 가운데 하나다.","어떤 사람은 여러 사람 앞에서 말할 때 심장이 빨리 뛰고 손에 땀이 나는데, 이것은 사실 정상적인 생리 반응이다."],"ow":[[["泛黄","fànhuáng","누렇게 바래다"],["线装","xiànzhuāng","실로 꿰맨 제본"],["古籍","gǔjí","고서"]],[["深海","shēnhǎi","심해"],["胆固醇","dǎngùchún","콜레스테롤"]],[["洪武","Hóngwǔ","홍무(명 연호)"],["周长","zhōucháng","둘레"],["城垣","chéngyuán","성벽"]],[["公共场合","gōnggòng chǎnghé","공공장소"],["生理","shēnglǐ","생리"]]]},{"o":["随着冷链物流的发展，产自南方的新鲜荔枝如今一两天内就能送到北方消费者手中。","剧烈运动后立即大量饮用冰水，容易刺激肠胃，甚至引发腹痛。","主办方特意邀请了几位那所大学长期研究甲骨文的著名学者，为市民举办公益讲座。","这片原始森林里生长着上千种植物，其中不少是国家重点保护的珍稀物种。"],"a":2,"type":"관형어 순서","why":"“那所大学”(소속)는 수량 “几位”보다 앞에 와야 한다.","fix":"主办方特意邀请了那所大学几位长期研究甲骨文的著名学者，为市民举办公益讲座。","words":[["冷链","lěngliàn","콜드체인"],["荔枝","lìzhī","리치"],["甲骨文","jiǎgǔwén","갑골문"],["公益","gōngyì","공익"],["珍稀","zhēnxī","진귀하고 드물다"]],"tr":["콜드체인 물류가 발달하면서 남방에서 난 신선한 리치를 이제는 하루이틀 만에 북방 소비자에게 보낼 수 있다.","격렬한 운동 직후 얼음물을 많이 마시면 위장을 자극하기 쉽고 심하면 복통이 생긴다.","주최 측은 그 대학에서 오랫동안 갑골문을 연구해 온 저명한 학자 몇 분을 특별히 모셔 시민을 위한 공익 강좌를 열었다.","이 원시림에는 천여 종의 식물이 자라는데, 그 가운데 상당수가 국가 중점 보호를 받는 희귀종이다."],"ow":[[["冷链","lěngliàn","콜드체인"],["物流","wùliú","물류"],["荔枝","lìzhī","리치"]],[["剧烈","jùliè","격렬하다"],["刺激","cìjī","자극하다"],["腹痛","fùtòng","복통"]],[["主办方","zhǔbànfāng","주최 측"],["甲骨文","jiǎgǔwén","갑골문"],["公益","gōngyì","공익"]],[["原始森林","yuánshǐ sēnlín","원시림"],["珍稀","zhēnxī","진귀하고 드물다"],["物种","wùzhǒng","종"]]]},{"o":["狼群有着严密的等级制度，捕猎时成员之间分工明确、配合默契。","大会经过三天的热烈讨论，最终通过并审议了《历史文化名城保护条例》的修订草案。","春秋时期的鲁班被后世尊为木匠的祖师，相传锯子、墨斗等工具都是他发明的。","有专家提醒，儿童过早接触电子屏幕，可能会对视力发育和语言能力造成不良影响。"],"a":1,"type":"동사·사건 순서","why":"먼저 심의하고 나서 통과시키므로 “审议并通过”가 맞다. “通过并审议”는 순서가 거꾸로다.","fix":"大会经过三天的热烈讨论，最终审议并通过了《历史文化名城保护条例》的修订草案。","words":[["默契","mòqì","손발이 잘 맞다"],["审议","shěnyì","심의하다"],["条例","tiáolì","조례"],["草案","cǎo'àn","초안"],["鲁班","Lǔ Bān","노반(춘추시대 장인)"],["墨斗","mòdǒu","먹통"]],"tr":["늑대 무리에는 엄격한 서열 제도가 있어서, 사냥할 때 구성원들의 역할 분담이 분명하고 손발이 잘 맞는다.","대회는 사흘 동안의 열띤 토론을 거쳐 마침내 《역사문화명성 보호 조례》 개정안을 심의하고 통과시켰다.","춘추시대의 노반은 후대에 목수의 시조로 받들어졌으며, 톱과 먹통 같은 도구를 모두 그가 발명했다고 전해진다.","한 전문가는 아이가 너무 일찍 전자 화면을 접하면 시력 발달과 언어 능력에 나쁜 영향을 줄 수 있다고 경고했다."],"ow":[[["等级","děngjí","서열"],["捕猎","bǔliè","사냥하다"],["默契","mòqì","손발이 잘 맞다"]],[["审议","shěnyì","심의하다"],["条例","tiáolì","조례"],["修订","xiūdìng","개정하다"],["草案","cǎo'àn","초안"]],[["鲁班","Lǔ Bān","노반"],["祖师","zǔshī","시조"],["锯子","jùzi","톱"],["墨斗","mòdǒu","먹통"]],[["屏幕","píngmù","화면"],["发育","fāyù","발달"]]]},{"o":["我国幅员辽阔，南北气候差异显著，因此各地的饮食习惯也大不相同。","量子计算机的运算速度远远超过传统计算机，在密码破译、药物研发等领域具有广阔的应用前景。","她通过长期的观察和记录，总结出了一套适合本地气候的蔬菜种植方法。","考古队员在清理墓室的过程中，先后取出并发现了一批色彩艳丽的汉代丝织品，随后将其送往实验室进行保护处理。"],"a":3,"type":"동사·사건 순서","why":"발견해야 꺼낼 수 있으므로 “发现并取出”가 맞다. “取出并发现”은 순서가 거꾸로다.","fix":"考古队员在清理墓室的过程中，先后发现并取出了一批色彩艳丽的汉代丝织品，随后将其送往实验室进行保护处理。","words":[["幅员辽阔","fú yuán liáo kuò","영토가 넓다"],["量子","liàngzǐ","양자"],["破译","pòyì","해독하다"],["墓室","mùshì","묘실"],["艳丽","yànlì","화려하다"]],"tr":["우리나라는 땅이 넓고 남북의 기후 차이가 뚜렷해서 지역마다 식습관도 크게 다르다.","양자 컴퓨터는 연산 속도가 기존 컴퓨터를 훨씬 뛰어넘어 암호 해독, 신약 개발 등의 분야에서 넓은 활용 가능성을 지닌다.","그녀는 오랜 관찰과 기록을 통해 이 지역 기후에 맞는 채소 재배법을 정리해 냈다.","고고학 대원들은 묘실을 정리하면서 색이 화려한 한대 비단 직물을 차례로 발견해 꺼냈고, 곧 실험실로 보내 보존 처리를 했다."],"ow":[[["幅员辽阔","fú yuán liáo kuò","영토가 넓다"],["显著","xiǎnzhù","뚜렷하다"],["大不相同","dà bù xiāng tóng","크게 다르다"]],[["量子","liàngzǐ","양자"],["运算","yùnsuàn","연산"],["破译","pòyì","해독하다"],["前景","qiánjǐng","전망"]],[["总结","zǒngjié","정리하다"],["种植","zhòngzhí","재배하다"]],[["墓室","mùshì","묘실"],["艳丽","yànlì","화려하다"],["丝织品","sīzhīpǐn","견직물"]]]}],[{"o":["京杭大运河北起北京、南达杭州，是世界上开凿最早、里程最长的人工运河。","即使遭遇了多次战火和地震，这座始建于辽代的木塔就依然巍然屹立，令人惊叹。","研究人员认为，海洋中的微塑料可能通过食物链进入人体，其潜在危害不容忽视。","这位工程师在设计中巧妙地融入了传统榫卯结构，使整座建筑在不用一颗钉子的情况下依然牢固。"],"a":1,"type":"짝 오류","why":"“即使”는 “也”와 짝을 이룬다. “即使……就”는 짝이 틀렸다.","fix":"即使遭遇了多次战火和地震，这座始建于辽代的木塔也依然巍然屹立，令人惊叹。","words":[["开凿","kāizáo","(운하를) 파다"],["巍然屹立","wēi rán yì lì","우뚝 솟아 있다"],["微塑料","wēisùliào","미세플라스틱"],["榫卯","sǔnmǎo","장부 이음"],["牢固","láogù","견고하다"]],"tr":["징항 대운하는 북쪽 베이징에서 남쪽 항저우까지 이어지는, 세계에서 가장 일찍 파고 가장 긴 인공 운하다.","여러 차례 전쟁과 지진을 겪었지만 요나라 때 처음 세운 이 목탑은 여전히 우뚝 서 있어 감탄을 자아낸다.","연구진은 바닷속 미세플라스틱이 먹이사슬을 거쳐 사람 몸에 들어올 수 있으며, 그 잠재적 위해를 가볍게 볼 수 없다고 본다.","이 기술자는 설계에 전통 장부 이음 구조를 솜씨 있게 녹여 넣어, 건물 전체가 못 하나 쓰지 않고도 튼튼하게 했다."],"ow":[[["京杭大运河","Jīng-Háng Dàyùnhé","징항 대운하"],["开凿","kāizáo","(운하를) 파다"],["里程","lǐchéng","거리"]],[["遭遇","zāoyù","겪다"],["辽代","Liáo dài","요나라"],["巍然屹立","wēi rán yì lì","우뚝 솟다"],["惊叹","jīngtàn","감탄하다"]],[["微塑料","wēisùliào","미세플라스틱"],["食物链","shíwùliàn","먹이사슬"],["潜在","qiánzài","잠재적"],["不容忽视","bù róng hū shì","간과할 수 없다"]],[["巧妙","qiǎomiào","교묘하다"],["榫卯","sǔnmǎo","장부 이음"],["牢固","láogù","견고하다"]]]},{"o":["由于长期缺乏有效保护，许多散落在民间的古代碑刻已经风化严重，字迹模糊难辨。","那些看似微不足道的生活习惯，日积月累，往往会对健康产生深远的影响。","云冈石窟开凿于北魏时期，现存主要洞窟四十五个，大小造像五万余尊。","古人认为，读书与其贪多求快，宁可精读细思，真正领会其中的义理。"],"a":3,"type":"짝 오류","why":"“与其”는 “不如”와 짝을 이룬다. “与其……宁可”는 짝이 틀렸다.","fix":"古人认为，读书与其贪多求快，不如精读细思，真正领会其中的义理。","words":[["碑刻","bēikè","비석 글씨"],["微不足道","wēi bù zú dào","하찮다"],["云冈石窟","Yúngāng Shíkū","윈강 석굴"],["造像","zàoxiàng","조상(불상)"],["义理","yìlǐ","글의 이치"]],"tr":["오랫동안 제대로 보호받지 못해 민간에 흩어진 옛 비석 글씨 상당수가 심하게 풍화되어 글자를 알아보기 어렵다.","하찮아 보이는 생활 습관도 오랜 시간 쌓이면 건강에 깊은 영향을 주는 경우가 많다.","윈강 석굴은 북위 시대에 파기 시작했으며, 지금 주요 석굴 45개와 크고 작은 불상 5만여 존이 남아 있다.","옛사람들은 책을 읽을 때 많이 빨리 읽으려 하기보다 정독하고 깊이 생각해 그 안의 이치를 제대로 깨달아야 한다고 보았다."],"ow":[[["散落","sànluò","흩어지다"],["碑刻","bēikè","비석 글씨"],["风化","fēnghuà","풍화"],["模糊","móhu","흐릿하다"]],[["微不足道","wēi bù zú dào","하찮다"],["日积月累","rì jī yuè lěi","오랜 시간 쌓이다"],["深远","shēnyuǎn","깊고 크다"]],[["云冈石窟","Yúngāng Shíkū","윈강 석굴"],["北魏","Běi Wèi","북위"],["洞窟","dòngkū","석굴"],["造像","zàoxiàng","불상"]],[["贪多求快","tān duō qiú kuài","많이 빨리 하려고 욕심내다"],["精读","jīngdú","정독하다"],["领会","lǐnghuì","깨닫다"],["义理","yìlǐ","이치"]]]},{"o":["无论是在城市还是在乡村，移动支付都已深入到人们生活的方方面面。","蝙蝠能在漆黑的夜里自如飞行，靠的是它们发出超声波并接收回声的本领。","虽然中医理论体系形成于两千多年前，而且其中许多养生观念至今仍被现代医学所借鉴。","这座古镇之所以至今保留着原汁原味的明清风貌，是因为它长期远离交通要道，较少受到外界干扰。"],"a":2,"type":"짝 오류","why":"“虽然”은 역접 “但(是)”와 짝을 이루어야 하는데 점층의 “而且”를 썼다.","fix":"虽然中医理论体系形成于两千多年前，但其中许多养生观念至今仍被现代医学所借鉴。","words":[["蝙蝠","biānfú","박쥐"],["超声波","chāoshēngbō","초음파"],["养生","yǎngshēng","양생, 건강 관리"],["借鉴","jièjiàn","참고하다, 본받다"],["原汁原味","yuán zhī yuán wèi","원래 모습 그대로"]],"tr":["도시든 농촌이든 모바일 결제는 이미 사람들 생활 구석구석까지 파고들었다.","박쥐가 칠흑 같은 밤에도 자유롭게 날 수 있는 것은 초음파를 내보내고 메아리를 받아들이는 능력 덕분이다.","중의학 이론 체계는 2천여 년 전에 만들어졌지만, 그 가운데 많은 양생 관념은 지금도 현대 의학이 참고하고 있다.","이 옛 마을이 지금까지 명청 시대 모습을 그대로 간직한 것은 오랫동안 큰 교통로에서 떨어져 바깥의 간섭을 덜 받았기 때문이다."],"ow":[[["移动支付","yídòng zhīfù","모바일 결제"],["方方面面","fāngfāng miànmiàn","구석구석"]],[["蝙蝠","biānfú","박쥐"],["漆黑","qīhēi","칠흑 같다"],["超声波","chāoshēngbō","초음파"],["回声","huíshēng","메아리"]],[["中医","zhōngyī","중의학"],["养生","yǎngshēng","양생"],["借鉴","jièjiàn","참고하다"]],[["原汁原味","yuán zhī yuán wèi","원래 모습 그대로"],["风貌","fēngmào","모습"],["要道","yàodào","주요 길목"],["干扰","gānrǎo","간섭"]]]},{"o":["不但永乐宫壁画规模宏大，而且艺术水平极高，堪称元代道教艺术的宝库。","这项政策实施以来，当地的空气质量明显改善，重污染天数比去年同期减少了一半。","狐狸的大尾巴不仅能帮助它在奔跑时保持平衡，冬天还能像围巾一样为身体保暖。","在成长的道路上，每个人都难免会经历挫折，关键在于能否从中吸取教训、重新出发。"],"a":0,"type":"관련사 위치","why":"앞뒤 절의 주어가 같으므로 “不但”은 주어 “永乐宫壁画” 뒤에 와야 한다.","fix":"永乐宫壁画不但规模宏大，而且艺术水平极高，堪称元代道教艺术的宝库。","words":[["永乐宫","Yǒnglè Gōng","영락궁"],["宏大","hóngdà","거대하다"],["宝库","bǎokù","보고"],["挫折","cuòzhé","좌절"],["吸取","xīqǔ","(교훈을) 얻다"]],"tr":["영락궁 벽화는 규모가 거대할 뿐 아니라 예술 수준도 매우 높아 원대 도교 예술의 보고라 할 만하다.","이 정책이 시행된 뒤 현지의 공기 질이 눈에 띄게 좋아져, 심한 오염 일수가 지난해 같은 기간보다 절반으로 줄었다.","여우의 큰 꼬리는 달릴 때 균형을 잡게 도와줄 뿐 아니라 겨울에는 목도리처럼 몸을 따뜻하게 감싸 준다.","자라는 길에서 누구나 좌절을 겪기 마련이며, 중요한 것은 그 속에서 교훈을 얻어 다시 출발할 수 있느냐다."],"ow":[[["永乐宫","Yǒnglè Gōng","영락궁"],["宏大","hóngdà","거대하다"],["堪称","kānchēng","~라 할 만하다"],["宝库","bǎokù","보고"]],[["实施","shíshī","시행하다"],["同期","tóngqī","같은 기간"]],[["狐狸","húli","여우"],["平衡","pínghéng","균형"],["保暖","bǎonuǎn","보온하다"]],[["难免","nánmiǎn","~하기 마련이다"],["挫折","cuòzhé","좌절"],["吸取","xīqǔ","얻다"]]]},{"o":["早在五千多年前，我国先民就已掌握了种桑养蚕、缫丝织绸的技术，丝绸也因此成为古代对外贸易的重要商品。","不少研究表明，长期独处的人更容易产生孤独感，进而影响心理健康。","在这场文化交流活动中，中国书法家不仅现场展示了行草技艺，外国艺术家也纷纷拿起毛笔体验书写的乐趣。","为了减少一次性塑料制品的使用，不少超市开始提供可降解购物袋。"],"a":2,"type":"관련사 위치","why":"앞뒤 절의 주어(中国书法家, 外国艺术家)가 다르므로 “不仅”은 주어 앞에 와야 한다.","fix":"在这场文化交流活动中，不仅中国书法家现场展示了行草技艺，外国艺术家也纷纷拿起毛笔体验书写的乐趣。","words":[["先民","xiānmín","선조"],["缫丝","sāosī","고치에서 실을 뽑다"],["进而","jìn'ér","나아가"],["行草","xíngcǎo","행초서"],["降解","jiàngjiě","분해되다"]],"tr":["이미 5천여 년 전에 우리 선조는 뽕나무를 심어 누에를 치고 실을 뽑아 비단을 짜는 기술을 익혔으며, 비단은 그로 인해 고대 대외 무역의 중요한 상품이 되었다.","많은 연구에 따르면 오래 혼자 지내는 사람은 외로움을 더 쉽게 느끼고 나아가 정신 건강에도 영향을 받는다.","이 문화 교류 행사에서 중국 서예가들이 현장에서 행초서 솜씨를 보여 주었을 뿐 아니라, 외국 예술가들도 앞다투어 붓을 들고 글씨 쓰는 재미를 맛보았다.","일회용 플라스틱 제품 사용을 줄이기 위해 많은 마트가 분해되는 쇼핑백을 제공하기 시작했다."],"ow":[[["先民","xiānmín","선조"],["养蚕","yǎngcán","누에를 치다"],["缫丝","sāosī","실을 뽑다"],["丝绸","sīchóu","비단"]],[["独处","dúchǔ","혼자 지내다"],["孤独感","gūdúgǎn","외로움"],["进而","jìn'ér","나아가"]],[["书法家","shūfǎjiā","서예가"],["行草","xíngcǎo","행초서"],["毛笔","máobǐ","붓"]],[["一次性","yícìxìng","일회용"],["降解","jiàngjiě","분해되다"]]]},{"o":["由于这座古寺坐落在海拔两千多米的山顶上，因此每年前来朝拜的香客仍然络绎不绝。","他退休后并没有闲着，而是加入了社区志愿者队伍，每天忙得不亦乐乎。","金字塔的建造方法至今众说纷纭，但它无疑代表了古埃及高超的建筑水平。","人工智能虽然能高效处理海量数据，但在情感理解和伦理判断方面仍存在明显不足。"],"a":0,"type":"논리 관계(인과 오용)","why":"높은 산 위에 있다는 것은 순례객이 많은 이유가 아니라 오히려 어려운 조건이므로 “由于……因此”가 아니라 “尽管……仍然”이어야 한다.","fix":"尽管这座古寺坐落在海拔两千多米的山顶上，每年前来朝拜的香客仍然络绎不绝。","words":[["朝拜","cháobài","참배하다"],["香客","xiāngkè","참배객"],["络绎不绝","luò yì bù jué","끊임없이 이어지다"],["不亦乐乎","bú yì lè hū","정신없이 바쁘다"],["众说纷纭","zhòng shuō fēn yún","의견이 분분하다"],["伦理","lúnlǐ","윤리"]],"tr":["이 옛 절은 해발 2천여 미터 산꼭대기에 있는데도 해마다 참배하러 오는 신도들의 발길이 끊이지 않는다.","그는 은퇴한 뒤 쉬지 않고 지역 자원봉사단에 들어가 날마다 정신없이 바쁘게 지낸다.","피라미드를 어떻게 지었는지는 지금도 의견이 분분하지만, 고대 이집트의 뛰어난 건축 수준을 보여 준다는 점은 의심할 여지가 없다.","인공지능은 방대한 데이터를 효율적으로 처리할 수 있지만 감정 이해와 윤리적 판단에서는 여전히 뚜렷한 한계가 있다."],"ow":[[["古寺","gǔsì","옛 절"],["坐落","zuòluò","자리 잡다"],["朝拜","cháobài","참배하다"],["络绎不绝","luò yì bù jué","끊임없이 이어지다"]],[["退休","tuìxiū","은퇴하다"],["志愿者","zhìyuànzhě","자원봉사자"],["不亦乐乎","bú yì lè hū","정신없이 바쁘다"]],[["金字塔","jīnzìtǎ","피라미드"],["众说纷纭","zhòng shuō fēn yún","의견이 분분하다"],["无疑","wúyí","의심할 바 없이"]],[["海量","hǎiliàng","방대한 양"],["伦理","lúnlǐ","윤리"]]]},{"o":["皮影戏是一种用灯光照射兽皮或纸板做成的人物剪影来表演故事的民间戏剧。","尽管这项实验多次失败，研究团队却从中积累了宝贵的数据，为后来的突破打下了基础。","一个城市的文明程度，往往体现在公共场所的细节之中。","这批西夏文献的内容极其深奥，不但研究西夏学多年的专家难以完全读懂，就连普通读者也无从理解。"],"a":3,"type":"논리 관계(점층 오용)","why":"점층은 쉬운 것에서 어려운 것으로 가야 한다. 전문가도 못 읽는다는 더 강한 말이 “就连” 뒤에 와야 하는데 순서가 거꾸로다.","fix":"这批西夏文献的内容极其深奥，不但普通读者无从理解，就连研究西夏学多年的专家也难以完全读懂。","words":[["剪影","jiǎnyǐng","실루엣"],["突破","tūpò","돌파"],["西夏","Xī Xià","서하(왕조)"],["深奥","shēn'ào","심오하다"],["无从","wúcóng","~할 길이 없다"]],"tr":["그림자극은 짐승 가죽이나 종이판으로 만든 인물 실루엣에 불빛을 비추어 이야기를 연기하는 민간 연극이다.","이 실험은 여러 번 실패했지만 연구팀은 그 과정에서 귀중한 데이터를 쌓아 뒷날의 돌파에 밑거름을 마련했다.","한 도시의 문명 수준은 흔히 공공장소의 세세한 부분에서 드러난다.","이 서하 문헌들은 내용이 매우 심오해서 서하학을 오래 연구한 전문가도 완전히 읽어 내기 어렵고 일반 독자는 더더욱 이해할 길이 없다."],"ow":[[["皮影戏","píyǐngxì","그림자극"],["兽皮","shòupí","짐승 가죽"],["剪影","jiǎnyǐng","실루엣"]],[["积累","jīlěi","쌓다"],["突破","tūpò","돌파"]],[["文明","wénmíng","문명"],["细节","xìjié","세부"]],[["西夏","Xī Xià","서하"],["文献","wénxiàn","문헌"],["深奥","shēn'ào","심오하다"],["无从","wúcóng","~할 길이 없다"]]]},{"o":["由于具有极强的适应能力，麻雀几乎遍布世界各地的城市和乡村。","黄公望是元代著名的山水画家，但是他晚年创作的《富春山居图》笔墨精妙，被誉为“画中之兰亭”。","合理的膳食结构应当以谷物为主，同时搭配适量的蔬果、肉类和奶制品。","越来越多的博物馆推出了线上展览，让人们足不出户就能欣赏到珍贵的文物。"],"a":1,"type":"논리 관계(역접 오용)","why":"유명한 화가이고 그의 그림이 훌륭하다는 것은 반대되는 내용이 아닌데 “但是”를 썼다.","fix":"黄公望是元代著名的山水画家，他晚年创作的《富春山居图》笔墨精妙，被誉为“画中之兰亭”。","words":[["遍布","biànbù","널리 퍼져 있다"],["黄公望","Huáng Gōngwàng","황공망(원대 화가)"],["富春山居图","Fùchūn Shānjū Tú","부춘산거도"],["笔墨","bǐmò","필묵, 화법"],["膳食","shànshí","식사, 음식"],["足不出户","zú bù chū hù","집 밖에 나가지 않다"]],"tr":["참새는 적응력이 매우 강해 세계 곳곳의 도시와 농촌에 거의 다 퍼져 있다.","황공망은 원대의 이름난 산수화가로, 그가 말년에 그린 《부춘산거도》는 필치가 정교해 ‘그림 가운데 난정서’라 불린다.","바람직한 식단은 곡물을 위주로 하면서 채소·과일·고기·유제품을 알맞게 곁들여야 한다.","점점 더 많은 박물관이 온라인 전시를 열어 사람들이 집을 나서지 않고도 귀중한 문화재를 감상할 수 있게 했다."],"ow":[[["麻雀","máquè","참새"],["遍布","biànbù","널리 퍼져 있다"]],[["黄公望","Huáng Gōngwàng","황공망"],["富春山居图","Fùchūn Shānjū Tú","부춘산거도"],["笔墨","bǐmò","필치"],["兰亭","Lántíng","난정서"]],[["膳食","shànshí","식사"],["谷物","gǔwù","곡물"],["奶制品","nǎizhìpǐn","유제품"]],[["足不出户","zú bù chū hù","집 밖에 나가지 않다"],["文物","wénwù","문화재"]]]},{"o":["对于如何保护好历史街区的传统风貌上，专家们提出了许多切实可行的建议。","春节贴春联的习俗由来已久，最早可以追溯到古人在桃木板上书写神名以驱邪的“桃符”。","一些候鸟能够连续飞行数千公里而不着陆，其耐力令人叹为观止。","这位企业家把公司的大部分利润投入到了公益事业中，赢得了社会各界的尊重。"],"a":0,"type":"개사 오용·섞임","why":"“对于……”와 “在……上” 두 구조가 섞여 “对于……上”이 되었다.","fix":"在如何保护好历史街区的传统风貌上，专家们提出了许多切实可行的建议。","words":[["风貌","fēngmào","풍모, 모습"],["切实可行","qiè shí kě xíng","실제로 실행 가능하다"],["驱邪","qūxié","잡귀를 쫓다"],["桃符","táofú","도부(복숭아나무 부적)"],["叹为观止","tàn wéi guān zhǐ","감탄을 금치 못하다"]],"tr":["역사 거리의 전통 모습을 어떻게 잘 지킬지에 대해 전문가들은 실제로 실행할 수 있는 제안을 많이 내놓았다.","춘절에 춘련을 붙이는 풍습은 유래가 깊어, 처음은 옛사람들이 복숭아나무 판에 신의 이름을 써서 잡귀를 쫓던 ‘도부’까지 거슬러 올라간다.","어떤 철새는 땅에 내리지 않고 수천 킬로미터를 날 수 있어, 그 지구력에 감탄을 금할 수 없다.","이 기업가는 회사 이익의 대부분을 공익사업에 쏟아 사회 각계의 존경을 받았다."],"ow":[[["街区","jiēqū","거리 구역"],["风貌","fēngmào","모습"],["切实可行","qiè shí kě xíng","실제로 실행 가능하다"]],[["春联","chūnlián","춘련"],["由来已久","yóu lái yǐ jiǔ","유래가 오래되다"],["驱邪","qūxié","잡귀를 쫓다"],["桃符","táofú","도부"]],[["着陆","zhuólù","착륙하다"],["耐力","nàilì","지구력"],["叹为观止","tàn wéi guān zhǐ","감탄을 금치 못하다"]],[["企业家","qǐyèjiā","기업가"],["利润","lìrùn","이윤"],["公益","gōngyì","공익"]]]},{"o":["经过几代人的接力治沙，昔日黄沙漫天的毛乌素沙地如今已披上了绿装。","胃里分泌的一种激素会在人饥饿时向大脑发出信号，使人产生想要进食的冲动。","在当地文物专家的悉心指导，村民们用传统工艺修复了这座有着三百多年历史的古戏台。","茶马古道是古代西南地区以马帮为主要运输方式的商贸通道，见证了汉藏等民族之间的交往。"],"a":2,"type":"개사 오용·섞임","why":"“在……指导” 뒤에 “下”가 빠져 개사 구조가 완성되지 않았다.","fix":"在当地文物专家的悉心指导下，村民们用传统工艺修复了这座有着三百多年历史的古戏台。","words":[["毛乌素","Máowūsù","마오우쑤(사막)"],["激素","jīsù","호르몬"],["悉心","xīxīn","정성을 다하다"],["戏台","xìtái","무대"],["茶马古道","Chámǎ Gǔdào","차마고도"],["马帮","mǎbāng","말 상단"]],"tr":["여러 세대가 이어서 모래를 다스린 끝에 예전에 누런 모래가 하늘을 덮던 마오우쑤 사막이 이제는 초록 옷을 입었다.","위에서 분비되는 한 호르몬은 배가 고플 때 뇌에 신호를 보내 무언가를 먹고 싶은 충동을 일으킨다.","현지 문화재 전문가의 세심한 지도 아래 마을 사람들은 전통 공법으로 300여 년 된 옛 무대를 복원했다.","차마고도는 옛 서남 지역에서 말 상단을 주된 운송 수단으로 삼던 교역로로, 한족과 티베트족 등 여러 민족의 교류를 지켜봐 왔다."],"ow":[[["接力","jiēlì","이어 달리다"],["治沙","zhìshā","사막화를 막다"],["昔日","xīrì","예전"],["毛乌素","Máowūsù","마오우쑤"]],[["分泌","fēnmì","분비하다"],["激素","jīsù","호르몬"],["冲动","chōngdòng","충동"]],[["悉心","xīxīn","정성을 다하다"],["修复","xiūfù","복원하다"],["戏台","xìtái","무대"]],[["茶马古道","Chámǎ Gǔdào","차마고도"],["马帮","mǎbāng","말 상단"],["商贸","shāngmào","상업 무역"],["见证","jiànzhèng","지켜보다"]]]}],[{"o":["初学书法的人难免会出现笔画生硬、结构失衡等问题，只要勤加练习便可逐渐改善。","漠河是中国纬度最高的县级行政区，冬季漫长而严寒，最低气温可达零下五十摄氏度左右。","为了避免珍贵的古画在展出过程中不受强光照射，博物馆特意将展厅的灯光调暗。","这家公司推出的新产品因设计新颖、价格合理，一上市便受到了消费者的追捧。"],"a":2,"type":"이중 부정","why":"“避免……不受”는 이중 부정이 되어 ‘강한 빛을 받게 하려고’라는 반대 뜻이 된다.","fix":"为了避免珍贵的古画在展出过程中受到强光照射，博物馆特意将展厅的灯光调暗。","words":[["难免","nánmiǎn","~하기 마련이다"],["生硬","shēngyìng","딱딱하다, 어색하다"],["漠河","Mòhé","모허"],["纬度","wěidù","위도"],["追捧","zhuīpěng","열광적으로 찾다"]],"tr":["서예를 처음 배우는 사람은 획이 딱딱하고 짜임이 균형을 잃는 문제가 생기기 마련이지만, 부지런히 연습하면 점점 나아진다.","모허는 중국에서 위도가 가장 높은 현급 행정구로, 겨울이 길고 혹독하며 최저 기온이 영하 50도 안팎까지 내려간다.","귀한 옛 그림이 전시되는 동안 강한 빛을 받지 않게 하려고 박물관은 일부러 전시실 조명을 어둡게 했다.","이 회사가 내놓은 신제품은 디자인이 참신하고 값이 적당해 출시되자마자 소비자들의 큰 인기를 끌었다."],"ow":[[["难免","nánmiǎn","~하기 마련이다"],["笔画","bǐhuà","획"],["生硬","shēngyìng","딱딱하다"],["失衡","shīhéng","균형을 잃다"]],[["漠河","Mòhé","모허"],["纬度","wěidù","위도"],["严寒","yánhán","혹한"]],[["避免","bìmiǎn","피하다"],["照射","zhàoshè","비추다"],["展厅","zhǎntīng","전시실"]],[["新颖","xīnyǐng","참신하다"],["上市","shàngshì","출시되다"],["追捧","zhuīpěng","열광적으로 찾다"]]]},{"o":["面对确凿的证据，这名嫌疑人再也无法否认自己没有参与过那起古墓盗掘案。","由于资金链断裂，这家开了半个多世纪的老牌书店不得不暂停营业。","地球上的淡水资源仅占总水量的不到百分之三，而且大部分以冰川的形式存在。","龙门石窟始凿于北魏孝文帝时期，此后历经四百余年的营造，现存窟龛两千三百多个。"],"a":0,"type":"이중 부정","why":"“无法否认……没有参与”는 결국 ‘참여하지 않았다’는 반대 뜻이 된다.","fix":"面对确凿的证据，这名嫌疑人再也无法否认自己参与过那起古墓盗掘案。","words":[["确凿","quèzáo","확실하다"],["嫌疑人","xiányírén","용의자"],["盗掘","dàojué","도굴하다"],["资金链","zījīnliàn","자금 흐름"],["龙门石窟","Lóngmén Shíkū","룽먼 석굴"],["窟龛","kūkān","석굴과 감실"]],"tr":["확실한 증거 앞에서 이 용의자는 더 이상 자신이 그 고분 도굴 사건에 가담했다는 사실을 부인할 수 없었다.","자금 흐름이 끊기는 바람에 반세기 넘게 문을 열어 온 이 오래된 서점은 영업을 잠시 멈출 수밖에 없었다.","지구의 담수 자원은 전체 물의 3%도 되지 않으며, 그나마 대부분이 빙하 형태로 존재한다.","룽먼 석굴은 북위 효문제 때 파기 시작해 이후 400여 년에 걸쳐 조성되었으며, 지금 석굴과 감실이 2,300여 개 남아 있다."],"ow":[[["确凿","quèzáo","확실하다"],["嫌疑人","xiányírén","용의자"],["否认","fǒurèn","부인하다"],["盗掘","dàojué","도굴하다"]],[["资金链","zījīnliàn","자금 흐름"],["断裂","duànliè","끊기다"],["不得不","bùdébù","~할 수밖에 없다"]],[["淡水","dànshuǐ","담수"],["冰川","bīngchuān","빙하"]],[["龙门石窟","Lóngmén Shíkū","룽먼 석굴"],["孝文帝","Xiàowéndì","효문제"],["营造","yíngzào","조성하다"],["窟龛","kūkān","석굴과 감실"]]]},{"o":["这次调查覆盖了全国三十多个省级行政区，样本具有广泛的代表性。","这项看似冷门的研究，未必不会在将来产生意想不到的应用价值。","海啸往往由海底地震引发，其在大洋中的传播速度可达每小时数百公里。","谁也不能否认，徐悲鸿笔下奔腾的骏马不是中国现代绘画史上极具辨识度的艺术形象。"],"a":3,"type":"이중 부정","why":"“不能否认……不是”로 부정이 세 번 겹쳐 ‘대표적인 이미지가 아니다’라는 반대 뜻이 된다.","fix":"谁也不能否认，徐悲鸿笔下奔腾的骏马是中国现代绘画史上极具辨识度的艺术形象。","words":[["样本","yàngběn","표본"],["冷门","lěngmén","인기 없는 분야"],["海啸","hǎixiào","해일"],["徐悲鸿","Xú Bēihóng","쉬베이훙(화가)"],["骏马","jùnmǎ","준마"],["辨识度","biànshídù","알아보기 쉬운 정도"]],"tr":["이번 조사는 전국 30여 개 성급 행정구를 포괄해 표본이 폭넓은 대표성을 지닌다.","별로 주목받지 못하는 듯한 이 연구가 앞으로 뜻밖의 활용 가치를 낳을 수도 있다.","해일은 흔히 해저 지진으로 일어나며, 큰 바다에서 퍼지는 속도는 시속 수백 킬로미터에 이른다.","쉬베이훙이 그린 내달리는 준마가 중국 현대 회화사에서 가장 알아보기 쉬운 예술 이미지 가운데 하나라는 점은 누구도 부인할 수 없다."],"ow":[[["覆盖","fùgài","포괄하다"],["样本","yàngběn","표본"],["代表性","dàibiǎoxìng","대표성"]],[["冷门","lěngmén","인기 없는 분야"],["未必","wèibì","반드시 ~은 아니다"],["意想不到","yì xiǎng bú dào","뜻밖이다"]],[["海啸","hǎixiào","해일"],["引发","yǐnfā","일으키다"],["大洋","dàyáng","대양"]],[["否认","fǒurèn","부인하다"],["徐悲鸿","Xú Bēihóng","쉬베이훙"],["骏马","jùnmǎ","준마"],["辨识度","biànshídù","알아보기 쉬운 정도"]]]},{"o":["近十年来，这座城市的公共绿地面积增加了一倍，市民的休闲空间大为拓展。","采用新型节水灌溉技术后，这片农田的用水量比过去减少了一倍，粮食产量却不降反升。","中国古代的科举制度始于隋朝，终于清末，延续了一千三百多年。","有些鸟类会模仿其他动物的叫声，以此迷惑天敌或吸引配偶。"],"a":1,"type":"배수 감소","why":"줄어드는 것은 “倍”로 말할 수 없다. “减少了一半”라고 해야 한다.","fix":"采用新型节水灌溉技术后，这片农田的用水量比过去减少了一半，粮食产量却不降反升。","words":[["拓展","tuòzhǎn","넓히다"],["灌溉","guàngài","관개"],["不降反升","bú jiàng fǎn shēng","줄지 않고 오히려 늘다"],["迷惑","míhuò","현혹하다"],["配偶","pèi'ǒu","짝"]],"tr":["최근 10년 동안 이 도시의 공공 녹지 면적이 두 배로 늘어 시민들의 여가 공간이 크게 넓어졌다.","새로운 절수형 관개 기술을 쓴 뒤 이 농지의 물 사용량은 예전보다 절반으로 줄었는데도 수확량은 오히려 늘었다.","중국 고대의 과거 제도는 수나라 때 시작해 청나라 말에 끝나기까지 1,300여 년 동안 이어졌다.","어떤 새는 다른 동물의 울음소리를 흉내 내어 천적을 헷갈리게 하거나 짝을 끌어들인다."],"ow":[[["绿地","lǜdì","녹지"],["拓展","tuòzhǎn","넓히다"]],[["节水","jiéshuǐ","절수"],["灌溉","guàngài","관개"],["不降反升","bú jiàng fǎn shēng","줄지 않고 오히려 늘다"]],[["科举","kējǔ","과거"],["隋朝","Suí cháo","수나라"],["延续","yánxù","이어지다"]],[["模仿","mófǎng","흉내 내다"],["迷惑","míhuò","현혹하다"],["配偶","pèi'ǒu","짝"]]]},{"o":["农历九月初九的重阳节有登高、赏菊、插茱萸等习俗，如今又被赋予了敬老的新内涵。","研究者发现，同一首曲子，人们在心情愉快和低落时听，感受往往大相径庭。","雅鲁藏布大峡谷长约五百公里，平均深度两千多米，是世界上最深的峡谷之一。","新一代芯片的体积比上一代缩小了三倍，耗电量也明显降低。"],"a":3,"type":"배수 감소","why":"“缩小了三倍”는 말이 안 된다. 줄어든 것은 분수로 “缩小到原来的三分之一”처럼 써야 한다.","fix":"新一代芯片的体积缩小到上一代的三分之一，耗电量也明显降低。","words":[["重阳节","Chóngyáng Jié","중양절"],["茱萸","zhūyú","수유(나무)"],["赋予","fùyǔ","부여하다"],["大相径庭","dà xiāng jìng tíng","크게 차이 나다"],["雅鲁藏布","Yǎlǔzàngbù","얄룽창포강"],["芯片","xīnpiàn","반도체 칩"]],"tr":["음력 9월 9일 중양절에는 높은 곳에 오르고 국화를 감상하며 수유 가지를 꽂는 풍습이 있으며, 지금은 어른을 공경한다는 새 의미도 더해졌다.","연구자들은 같은 곡이라도 기분이 좋을 때와 가라앉을 때 들으면 느낌이 크게 다르다는 것을 알아냈다.","얄룽창포 대협곡은 길이가 약 500킬로미터, 평균 깊이가 2천여 미터로, 세계에서 가장 깊은 협곡 가운데 하나다.","새 세대 칩은 크기가 이전 세대의 3분의 1로 줄었고 전력 소모도 눈에 띄게 낮아졌다."],"ow":[[["重阳节","Chóngyáng Jié","중양절"],["茱萸","zhūyú","수유"],["赋予","fùyǔ","부여하다"],["内涵","nèihán","의미"]],[["低落","dīluò","가라앉다"],["大相径庭","dà xiāng jìng tíng","크게 차이 나다"]],[["雅鲁藏布","Yǎlǔzàngbù","얄룽창포"],["峡谷","xiágǔ","협곡"]],[["芯片","xīnpiàn","칩"],["耗电量","hàodiànliàng","전력 소모량"]]]},{"o":["茶叶按加工工艺的不同，大致可分为绿茶、红茶、乌龙茶、白茶、黄茶和黑茶六大类。","这次展览共展出了书画、瓷器、玉器、古籍和文物两百余件，吸引了大批市民前来参观。","他的作品题材广泛，既有反映乡村生活的小说，也有探讨历史问题的散文。","这款手机的电池续航时间比上一代延长了约三分之一。"],"a":1,"type":"범위·분류 오류","why":"“书画、瓷器、玉器、古籍”는 모두 “文物”에 속하는데 같은 층위로 나란히 늘어놓았다.","fix":"这次展览共展出了书画、瓷器、玉器、古籍等文物两百余件，吸引了大批市民前来参观。","words":[["工艺","gōngyì","공예, 공정"],["乌龙茶","wūlóngchá","우롱차"],["玉器","yùqì","옥기"],["题材","tícái","소재"],["探讨","tàntǎo","탐구하다"]],"tr":["찻잎은 가공 방식에 따라 크게 녹차·홍차·우롱차·백차·황차·흑차의 여섯 종류로 나눌 수 있다.","이번 전시회에는 서화·자기·옥기·고서 등 문화재 200여 점이 나와 많은 시민이 관람하러 왔다.","그의 작품은 소재가 다양해 농촌 생활을 그린 소설도 있고 역사 문제를 다룬 산문도 있다.","이 휴대폰의 배터리 사용 시간은 이전 세대보다 약 3분의 1 늘었다."],"ow":[[["工艺","gōngyì","공정"],["乌龙茶","wūlóngchá","우롱차"],["大致","dàzhì","대체로"]],[["书画","shūhuà","서화"],["瓷器","cíqì","자기"],["玉器","yùqì","옥기"]],[["题材","tícái","소재"],["探讨","tàntǎo","탐구하다"],["散文","sǎnwén","산문"]],[["续航","xùháng","사용 지속"],["延长","yáncháng","늘이다"]]]},{"o":["经过数十年的植树造林，我国森林覆盖率已从新中国成立初期的不足百分之九提高到百分之二十四以上。","酸奶中含有的乳酸菌有助于调节肠道环境，但并非所有人都适合大量饮用。","来自世界各地的一百多位中外学者和外国专家齐聚北京，围绕《论语》的海外译介问题展开了深入研讨。","这位钢琴家演奏时情感细腻、技巧娴熟，台下观众无不为之动容。"],"a":2,"type":"범위·분류 오류","why":"“中外学者”에 이미 외국 학자가 들어 있어 “外国专家”와 범위가 겹친다.","fix":"来自世界各地的一百多位中外学者齐聚北京，围绕《论语》的海外译介问题展开了深入研讨。","words":[["覆盖率","fùgàilǜ","피복률"],["乳酸菌","rǔsuānjūn","유산균"],["齐聚","qíjù","한자리에 모이다"],["译介","yìjiè","번역 소개"],["娴熟","xiánshú","능숙하다"],["动容","dòngróng","감동하다"]],"tr":["수십 년 동안 나무를 심어 숲을 가꾼 끝에 우리나라의 산림 피복률은 건국 초기의 9% 미만에서 24% 이상으로 높아졌다.","요구르트에 든 유산균은 장 환경을 조절하는 데 도움이 되지만, 모든 사람이 많이 마셔도 되는 것은 아니다.","세계 각지에서 온 백여 명의 학자가 베이징에 모여 《논어》의 해외 번역·소개 문제를 깊이 논의했다.","이 피아니스트는 연주할 때 감정이 섬세하고 기교가 능숙해 객석의 관객 모두가 감동했다."],"ow":[[["植树造林","zhí shù zào lín","나무를 심어 숲을 만들다"],["覆盖率","fùgàilǜ","피복률"]],[["乳酸菌","rǔsuānjūn","유산균"],["调节","tiáojié","조절하다"],["并非","bìngfēi","결코 ~이 아니다"]],[["齐聚","qíjù","한자리에 모이다"],["论语","Lúnyǔ","논어"],["译介","yìjiè","번역 소개"],["研讨","yántǎo","논의하다"]],[["细腻","xìnì","섬세하다"],["娴熟","xiánshú","능숙하다"],["无不","wúbù","모두 ~하다"],["动容","dòngróng","감동하다"]]]},{"o":["从出土的器物判断，这座墓葬的主人肯定大概是一位地位显赫的西汉诸侯王。","风筝起源于中国，最初被用于军事侦察和传递信息，后来才逐渐演变为一种娱乐用品。","每天保证七到八小时的睡眠，对于处在生长发育关键期的青少年而言尤为重要。","由于长期过度放牧，这片草原的沙化面积在短短十年间扩大了近一倍。"],"a":0,"type":"자기모순","why":"“肯定”(확실)과 “大概”(추측)가 함께 쓰여 앞뒤가 모순된다.","fix":"从出土的器物判断，这座墓葬的主人大概是一位地位显赫的西汉诸侯王。","words":[["墓葬","mùzàng","무덤"],["显赫","xiǎnhè","권세가 대단하다"],["诸侯王","zhūhóuwáng","제후왕"],["侦察","zhēnchá","정찰하다"],["放牧","fàngmù","방목하다"]],"tr":["출토된 유물로 보아 이 무덤의 주인은 아마 지위가 대단했던 서한의 제후왕일 것이다.","연은 중국에서 시작되었으며, 처음에는 군사 정찰과 정보 전달에 쓰이다가 나중에 놀이 도구로 바뀌었다.","매일 일곱에서 여덟 시간 잠을 자는 것은 성장 발육의 중요한 시기에 있는 청소년에게 특히 중요하다.","오랜 과도한 방목으로 이 초원의 사막화 면적이 불과 10년 사이에 거의 두 배로 늘었다."],"ow":[[["器物","qìwù","기물"],["墓葬","mùzàng","무덤"],["显赫","xiǎnhè","권세가 대단하다"],["诸侯王","zhūhóuwáng","제후왕"]],[["风筝","fēngzheng","연"],["侦察","zhēnchá","정찰하다"],["演变","yǎnbiàn","변화하다"]],[["发育","fāyù","발육"],["尤为","yóuwéi","특히"]],[["放牧","fàngmù","방목하다"],["沙化","shāhuà","사막화"]]]},{"o":["宋代的商业十分繁荣，世界上最早的纸币“交子”就诞生于北宋时期的四川。","大熊猫是中国特有的珍稀动物，也是世界上唯一以竹子为主食的熊科动物之一。","不少人以为多吃保健品就能延年益寿，其实均衡饮食和适量运动才是健康的根本。","他为人低调，从不在公开场合炫耀自己取得的成就。"],"a":1,"type":"자기모순","why":"“唯一”(오직 하나)과 “之一”(여럿 중 하나)이 함께 쓰여 모순된다.","fix":"大熊猫是中国特有的珍稀动物，也是世界上唯一以竹子为主食的熊科动物。","words":[["交子","jiāozǐ","교자(북송의 지폐)"],["熊科","xióngkē","곰과"],["延年益寿","yán nián yì shòu","수명을 늘리다"],["低调","dīdiào","겸손하다, 드러내지 않다"],["炫耀","xuànyào","자랑하다"]],"tr":["송대는 상업이 매우 번성해서 세계 최초의 지폐 ‘교자’가 북송 시기 쓰촨에서 탄생했다.","판다는 중국에만 사는 희귀 동물로, 세계에서 유일하게 대나무를 주식으로 삼는 곰과 동물이다.","많은 사람이 건강식품을 많이 먹으면 오래 살 수 있다고 여기지만, 사실은 균형 잡힌 식사와 적당한 운동이 건강의 근본이다.","그는 성품이 겸손해 공개적인 자리에서 자기가 이룬 성과를 자랑한 적이 없다."],"ow":[[["繁荣","fánróng","번영하다"],["纸币","zhǐbì","지폐"],["交子","jiāozǐ","교자"],["诞生","dànshēng","탄생하다"]],[["珍稀","zhēnxī","진귀하고 드물다"],["主食","zhǔshí","주식"],["熊科","xióngkē","곰과"]],[["保健品","bǎojiànpǐn","건강식품"],["延年益寿","yán nián yì shòu","수명을 늘리다"],["均衡","jūnhéng","균형 잡히다"]],[["低调","dīdiào","드러내지 않다"],["炫耀","xuànyào","자랑하다"]]]},{"o":["宣纸质地柔韧、洁白细密，且不易蛀蚀，因此有“纸寿千年”的美誉。","越来越多的城市开始推行垃圾分类，以提高资源的回收利用率。","心理学家发现，人在疲惫时更容易做出冲动的决定，因此重要的事情最好不要在深夜拍板。","这次出土的十二件青铜礼器中，九件保存完好，另有五件因锈蚀严重而残缺不全。"],"a":3,"type":"자기모순(숫자)","why":"열두 점 중 아홉 점이 온전하면 나머지는 세 점인데 “五件”이라 해 숫자가 맞지 않는다.","fix":"这次出土的十二件青铜礼器中，九件保存完好，另有三件因锈蚀严重而残缺不全。","words":[["宣纸","xuānzhǐ","선지(서화용 종이)"],["柔韧","róurèn","부드럽고 질기다"],["蛀蚀","zhùshí","좀먹다"],["拍板","pāibǎn","결정을 내리다"],["锈蚀","xiùshí","녹슬어 부식되다"],["残缺不全","cán quē bù quán","온전하지 못하다"]],"tr":["선지는 질기면서 부드럽고 희고 촘촘하며 좀이 잘 슬지 않아 ‘종이 수명이 천 년’이라는 찬사를 듣는다.","점점 더 많은 도시가 쓰레기 분리배출을 시행해 자원 재활용률을 높이려 하고 있다.","심리학자들은 사람이 지쳤을 때 충동적인 결정을 내리기 쉬우므로 중요한 일은 늦은 밤에 결정하지 않는 편이 좋다는 것을 발견했다.","이번에 출토된 청동 예기 열두 점 가운데 아홉 점은 잘 보존되어 있고, 나머지 몇 점은 녹이 심해 온전하지 못하다."],"ow":[[["宣纸","xuānzhǐ","선지"],["柔韧","róurèn","부드럽고 질기다"],["蛀蚀","zhùshí","좀먹다"],["美誉","měiyù","명성"]],[["推行","tuīxíng","시행하다"],["垃圾分类","lājī fēnlèi","쓰레기 분리배출"],["回收","huíshōu","회수하다"]],[["疲惫","píbèi","지치다"],["冲动","chōngdòng","충동적이다"],["拍板","pāibǎn","결정을 내리다"]],[["出土","chūtǔ","출토되다"],["礼器","lǐqì","예기"],["锈蚀","xiùshí","녹슬다"],["残缺不全","cán quē bù quán","온전하지 못하다"]]]}],[{"o":["蒙古族的那达慕大会历史悠久，摔跤、赛马、射箭被称为“男儿三艺”，是大会的核心项目。","正是凭借着对细节近乎苛刻的追求，这位设计师的作品才在国际上赢得了广泛赞誉。","地下水一旦遭到污染，治理起来往往需要数十年甚至上百年的时间。","这座明代古桥坍塌的主要原因，是长期超负荷通行和缺乏日常维护造成的。"],"a":3,"type":"구식 혼합","why":"“原因是……”와 “……是……造成的” 두 구조가 섞였다.","fix":"这座明代古桥坍塌的主要原因，是长期超负荷通行和缺乏日常维护。","words":[["那达慕","Nàdámù","나담 축제"],["摔跤","shuāijiāo","씨름"],["苛刻","kēkè","가혹하다, 까다롭다"],["赞誉","zànyù","찬사"],["坍塌","tāntā","무너지다"],["超负荷","chāofùhè","과부하"]],"tr":["몽골족의 나담 축제는 역사가 오래되었으며, 씨름·말 달리기·활쏘기는 ‘남자의 세 가지 재주’라 불리는 축제의 핵심 종목이다.","세부 사항을 거의 가혹할 만큼 따지는 집념 덕분에 이 디자이너의 작품은 국제적으로 폭넓은 찬사를 받았다.","지하수는 한번 오염되면 정화하는 데 수십 년, 길게는 백 년 넘게 걸리는 경우가 많다.","이 명대 옛 다리가 무너진 주된 원인은 오랜 과적 통행과 일상적인 관리 부족이다."],"ow":[[["蒙古族","Měnggǔzú","몽골족"],["那达慕","Nàdámù","나담"],["摔跤","shuāijiāo","씨름"],["射箭","shèjiàn","활쏘기"]],[["凭借","píngjiè","~에 힘입다"],["苛刻","kēkè","가혹하다"],["赞誉","zànyù","찬사"]],[["污染","wūrǎn","오염"],["治理","zhìlǐ","정화하다"]],[["坍塌","tāntā","무너지다"],["超负荷","chāo fùhè","과부하"],["维护","wéihù","유지 보수"]]]},{"o":["这个偏远山村的经济收入，过去主要靠种植茶叶和采集山货为主，如今乡村旅游已成为新的支柱产业。","苗族银饰工艺繁复、造型精美，银饰的多少往往被视为家庭财富的象征。","尽管各项指标均已达标，研发团队仍坚持对产品进行了长达半年的反复测试。","浩瀚的宇宙中可能存在着无数颗类地行星，但迄今为止，人类尚未发现任何确凿的地外生命迹象。"],"a":0,"type":"구식 혼합","why":"“靠……”와 “以……为主” 두 구조가 섞여 “靠……为主”가 되었다.","fix":"这个偏远山村的经济收入，过去主要靠种植茶叶和采集山货，如今乡村旅游已成为新的支柱产业。","words":[["山货","shānhuò","산나물·버섯 등 산물"],["支柱产业","zhīzhù chǎnyè","기간산업"],["繁复","fánfù","복잡하다"],["浩瀚","hàohàn","광대하다"],["迄今为止","qì jīn wéi zhǐ","지금까지"],["迹象","jìxiàng","징후, 흔적"]],"tr":["이 외딴 산골 마을의 소득은 예전에 주로 차 재배와 산나물 채취에 기댔지만, 지금은 농촌 관광이 새로운 주력 산업이 되었다.","먀오족 은장식은 공예가 복잡하고 모양이 정교하며, 은장식의 많고 적음은 흔히 집안 재산의 상징으로 여겨진다.","모든 지표가 이미 기준을 충족했지만 연구 개발팀은 여전히 제품을 반년 동안 거듭 시험하는 것을 고집했다.","광대한 우주에는 지구형 행성이 무수히 있을지도 모르지만, 지금까지 인류는 확실한 외계 생명의 흔적을 하나도 찾지 못했다."],"ow":[[["偏远","piānyuǎn","외지다"],["山货","shānhuò","산나물·버섯 등 산물"],["支柱产业","zhīzhù chǎnyè","기간산업"]],[["苗族","Miáozú","먀오족"],["银饰","yínshì","은장식"],["繁复","fánfù","복잡하다"],["象征","xiàngzhēng","상징"]],[["指标","zhǐbiāo","지표"],["达标","dábiāo","기준을 충족하다"],["研发","yánfā","연구 개발"]],[["浩瀚","hàohàn","광대하다"],["类地行星","lèidì xíngxīng","지구형 행성"],["迄今为止","qì jīn wéi zhǐ","지금까지"],["迹象","jìxiàng","흔적"]]]},{"o":["马可·波罗在游记中对元朝大都的繁华作了详尽描述，激发了欧洲人对东方的无限向往。","一部文艺作品能否经得起时间的考验，关键在于其思想内涵和艺术品质起着决定性作用。","这项调查以城市年轻上班族为对象，旨在了解他们的消费观念和储蓄习惯。","随着年龄的增长，人体内的胶原蛋白逐渐流失，皮肤也会变得松弛。"],"a":1,"type":"구식 혼합","why":"“关键在于……”와 “……起着决定性作用” 두 구조가 섞였다.","fix":"一部文艺作品能否经得起时间的考验，关键在于其思想内涵和艺术品质。","words":[["马可·波罗","Mǎkě Bōluó","마르코 폴로"],["详尽","xiángjìn","상세하다"],["内涵","nèihán","내용, 함의"],["旨在","zhǐzài","~을 목적으로 하다"],["胶原蛋白","jiāoyuán dànbái","콜라겐"],["松弛","sōngchí","느슨해지다"]],"tr":["마르코 폴로는 여행기에서 원나라 대도의 번화함을 자세히 묘사해, 동방에 대한 유럽인의 끝없는 동경을 불러일으켰다.","한 문예 작품이 시간의 시험을 견딜 수 있는지는 그 사상적 내용과 예술적 품질에 결정적으로 달려 있다.","이 조사는 도시의 젊은 직장인을 대상으로 그들의 소비 관념과 저축 습관을 알아보는 데 목적이 있다.","나이가 들면서 몸속 콜라겐이 점점 빠져나가 피부도 느슨해진다."],"ow":[[["马可·波罗","Mǎkě Bōluó","마르코 폴로"],["大都","Dàdū","대도(원 수도)"],["详尽","xiángjìn","상세하다"],["向往","xiàngwǎng","동경"]],[["考验","kǎoyàn","시험"],["内涵","nèihán","내용"],["决定性","juédìngxìng","결정적인"]],[["旨在","zhǐzài","~을 목적으로 하다"],["储蓄","chǔxù","저축"]],[["胶原蛋白","jiāoyuán dànbái","콜라겐"],["流失","liúshī","빠져나가다"],["松弛","sōngchí","느슨해지다"]]]},{"o":["华佗是东汉末年的名医，相传他发明了麻醉药“麻沸散”，还创编了模仿五种动物动作的“五禽戏”。","这款软件上线不到一年，用户数量已突破五千万，增长速度之快出乎所有人的意料。","专家认为，这一地区近年来频繁出现沙尘天气，是植被遭到严重破坏所致的结果。","适度的竞争可以激发团队成员的积极性，但过度竞争则可能破坏彼此之间的合作。"],"a":2,"type":"구식 혼합","why":"“是……所致”와 “是……的结果” 두 구조가 섞였다.","fix":"专家认为，这一地区近年来频繁出现沙尘天气，是植被遭到严重破坏所致。","words":[["华佗","Huà Tuó","화타(동한 명의)"],["麻醉","mázuì","마취"],["五禽戏","wǔqínxì","오금희(체조)"],["植被","zhíbèi","식생"],["所致","suǒzhì","~로 인한 것"],["激发","jīfā","불러일으키다"]],"tr":["화타는 동한 말기의 명의로, 마취약 ‘마비산’을 발명하고 다섯 동물의 동작을 본뜬 체조 ‘오금희’를 만들었다고 전해진다.","이 앱은 출시 1년도 안 되어 사용자가 5천만 명을 넘었는데, 그 성장 속도가 모두의 예상을 뛰어넘었다.","전문가들은 이 지역에 최근 몇 년 사이 황사가 잦은 것이 식생이 심하게 파괴되었기 때문이라고 본다.","적당한 경쟁은 팀원들의 의욕을 북돋을 수 있지만, 지나친 경쟁은 서로의 협력을 망가뜨릴 수 있다."],"ow":[[["华佗","Huà Tuó","화타"],["麻醉","mázuì","마취"],["麻沸散","máfèisǎn","마비산"],["五禽戏","wǔqínxì","오금희"]],[["上线","shàngxiàn","출시하다"],["突破","tūpò","돌파하다"],["意料","yìliào","예상"]],[["频繁","pínfán","잦다"],["沙尘","shāchén","황사"],["植被","zhíbèi","식생"]],[["激发","jīfā","북돋우다"],["积极性","jījíxìng","의욕"],["彼此","bǐcǐ","서로"]]]},{"o":["自从被列入世界文化遗产名录以来，让这座默默无闻的古村落一下子成了热门旅游目的地。","一个人的知识储备越丰富，他看待问题的视角往往就越多元。","北方的四合院讲究坐北朝南，这样既能保证冬季的采光，又能抵御凛冽的北风。","这家工厂引进智能化生产线后，产品合格率明显提升，人工成本则大幅下降。"],"a":0,"type":"주어 결여","why":"“自从……以来，让……” 때문에 “古村落”가 “让”의 목적어가 되어 주어가 없다.","fix":"自从被列入世界文化遗产名录以来，这座默默无闻的古村落一下子成了热门旅游目的地。","words":[["默默无闻","mò mò wú wén","이름 없이 조용하다"],["储备","chǔbèi","비축, 쌓아 둔 것"],["视角","shìjiǎo","시각"],["四合院","sìhéyuàn","사합원"],["凛冽","lǐnliè","살을 에듯 춥다"]],"tr":["세계문화유산 목록에 오른 뒤로, 이름 없이 조용하던 이 옛 마을은 단숨에 인기 관광지가 되었다.","지식을 많이 쌓은 사람일수록 문제를 바라보는 시각이 대체로 더 다양하다.","북방의 사합원은 남쪽을 향해 앉히는 것을 중시하는데, 그래야 겨울철 햇빛을 받으면서 매서운 북풍도 막을 수 있다.","이 공장은 스마트 생산 라인을 들인 뒤 제품 합격률이 눈에 띄게 높아지고 인건비는 크게 줄었다."],"ow":[[["名录","mínglù","목록"],["默默无闻","mò mò wú wén","이름 없이 조용하다"],["村落","cūnluò","마을"]],[["储备","chǔbèi","비축"],["视角","shìjiǎo","시각"],["多元","duōyuán","다양하다"]],[["四合院","sìhéyuàn","사합원"],["坐北朝南","zuò běi cháo nán","남향으로 앉다"],["采光","cǎiguāng","채광"],["凛冽","lǐnliè","살을 에듯 춥다"]],[["智能化","zhìnénghuà","스마트화"],["合格率","hégélǜ","합격률"],["成本","chéngběn","비용"]]]},{"o":["乌镇将千年古镇的保护与现代会展经济相结合，探索出了一条独具特色的发展之路。","即便是经验丰富的登山者，在攀登海拔八千米以上的山峰时也不敢掉以轻心。","生物钟紊乱不仅会影响睡眠质量，还与肥胖、糖尿病等多种慢性疾病密切相关。","为了防止这批明清刻本不被虫蛀霉变，图书馆每年都会对书库进行除湿和熏蒸处理。"],"a":3,"type":"이중 부정","why":"“防止……不被”는 이중 부정이 되어 ‘벌레 먹게 하려고’라는 반대 뜻이 된다.","fix":"为了防止这批明清刻本被虫蛀霉变，图书馆每年都会对书库进行除湿和熏蒸处理。","words":[["乌镇","Wūzhèn","우전(수향 마을)"],["掉以轻心","diào yǐ qīng xīn","방심하다"],["刻本","kèběn","목판본"],["霉变","méibiàn","곰팡이가 슬다"],["熏蒸","xūnzhēng","훈증하다"]],"tr":["우전은 천 년 된 옛 마을의 보존과 현대 전시·회의 산업을 결합해 독특한 발전의 길을 찾아냈다.","경험이 풍부한 등산가라도 해발 8천 미터가 넘는 산을 오를 때는 감히 방심하지 못한다.","생체 시계가 흐트러지면 수면의 질에 영향을 줄 뿐 아니라 비만·당뇨병 같은 여러 만성 질환과도 밀접한 관련이 있다.","이 명청 시대 목판본들이 벌레 먹거나 곰팡이 슬지 않도록 도서관은 해마다 서고를 제습하고 훈증 처리한다."],"ow":[[["乌镇","Wūzhèn","우전"],["会展","huìzhǎn","전시·회의"],["独具特色","dú jù tè sè","독특하다"]],[["攀登","pāndēng","오르다"],["海拔","hǎibá","해발"],["掉以轻心","diào yǐ qīng xīn","방심하다"]],[["生物钟","shēngwùzhōng","생체 시계"],["紊乱","wěnluàn","흐트러지다"],["糖尿病","tángniàobìng","당뇨병"],["慢性","mànxìng","만성"]],[["刻本","kèběn","목판본"],["虫蛀","chóngzhù","벌레 먹다"],["霉变","méibiàn","곰팡이 슬다"],["熏蒸","xūnzhēng","훈증하다"]]]},{"o":["《史记》是西汉史学家司马迁撰写的一部纪传体通史，记载了上起黄帝、下至汉武帝时期约三千年的历史。","适量饮用咖啡可以提神醒脑，但空腹饮用则可能刺激胃黏膜，引起不适。","这片湿地是丹顶鹤等珍稀鸟类的重要栖息地，保护好它的生态环境，是周边每一位居民共同都应该承担的责任。","这项发明虽然看似简单，却巧妙地解决了困扰业界多年的难题。"],"a":2,"type":"부사·능원동사 위치","why":"부사 “都”와 능원동사 “应该”는 “共同” 앞에 와야 한다. “共同都应该承担”은 어순이 틀렸다.","fix":"这片湿地是丹顶鹤等珍稀鸟类的重要栖息地，保护好它的生态环境，是周边每一位居民都应该共同承担的责任。","words":[["司马迁","Sīmǎ Qiān","사마천"],["纪传体","jìzhuàntǐ","기전체"],["黏膜","niánmó","점막"],["丹顶鹤","dāndǐnghè","두루미"],["困扰","kùnrǎo","괴롭히다"]],"tr":["《사기》는 서한의 역사가 사마천이 쓴 기전체 통사로, 위로는 황제부터 아래로는 한 무제 때까지 약 3천 년의 역사를 기록했다.","커피를 적당히 마시면 정신이 맑아지지만, 빈속에 마시면 위 점막을 자극해 속이 불편해질 수 있다.","이 습지는 두루미 등 희귀 조류의 중요한 서식지로, 그 생태 환경을 잘 지키는 것은 주변 주민 모두가 함께 져야 할 책임이다.","이 발명은 단순해 보이지만 업계를 여러 해 괴롭혀 온 난제를 교묘하게 풀어냈다."],"ow":[[["史记","Shǐjì","사기"],["司马迁","Sīmǎ Qiān","사마천"],["纪传体","jìzhuàntǐ","기전체"],["通史","tōngshǐ","통사"]],[["提神醒脑","tí shén xǐng nǎo","정신을 맑게 하다"],["空腹","kōngfù","빈속"],["黏膜","niánmó","점막"]],[["湿地","shīdì","습지"],["丹顶鹤","dāndǐnghè","두루미"],["栖息地","qīxīdì","서식지"]],[["巧妙","qiǎomiào","교묘하다"],["困扰","kùnrǎo","괴롭히다"],["难题","nántí","난제"]]]},{"o":["恐龙在地球上生存了约一亿六千万年，至今人们对其灭绝的原因仍存在诸多争议。","只有将古村落的保护与村民生活的改善结合起来，传统村落的保护工作就能真正落到实处。","面对网络上真假难辨的信息，我们不应急于转发，而应先核实其来源。","越窑青瓷是唐代南方青瓷的代表，其釉色青翠莹润，被诗人誉为“千峰翠色”。"],"a":1,"type":"짝 오류","why":"“只有”는 “才”와 짝을 이룬다. “只有……就”는 짝이 틀렸다.","fix":"只有将古村落的保护与村民生活的改善结合起来，传统村落的保护工作才能真正落到实处。","words":[["灭绝","mièjué","멸종하다"],["诸多","zhūduō","많은"],["落到实处","luò dào shí chù","실제로 효과를 내다"],["核实","héshí","사실을 확인하다"],["越窑","Yuèyáo","월요(당대 청자 가마)"],["莹润","yíngrùn","맑고 윤기 있다"]],"tr":["공룡은 지구에서 약 1억 6천만 년 동안 살았지만, 지금까지도 그 멸종 원인을 두고 논란이 많다.","옛 마을의 보존과 주민 생활 개선을 함께 묶어야만 전통 마을 보존 작업이 실제로 효과를 낼 수 있다.","인터넷에서 진위를 가리기 어려운 정보를 만나면 서둘러 퍼뜨리지 말고 먼저 출처를 확인해야 한다.","월요 청자는 당대 남방 청자의 대표로, 유약 빛깔이 푸르고 맑아 시인에게서 ‘천 봉우리의 푸른빛’이라는 찬사를 받았다."],"ow":[[["恐龙","kǒnglóng","공룡"],["灭绝","mièjué","멸종하다"],["诸多","zhūduō","많은"],["争议","zhēngyì","논란"]],[["古村落","gǔcūnluò","옛 마을"],["落到实处","luò dào shí chù","실제로 효과를 내다"]],[["真假难辨","zhēn jiǎ nán biàn","진위를 가리기 어렵다"],["转发","zhuǎnfā","퍼뜨리다"],["核实","héshí","확인하다"]],[["越窑","Yuèyáo","월요"],["青瓷","qīngcí","청자"],["釉色","yòusè","유약 빛깔"],["莹润","yíngrùn","맑고 윤기 있다"]]]},{"o":["据统计，参与此次问卷调查的市民中，超过半数以上的人表示曾在春节期间观看过线上庙会直播。","为了拯救濒危的中华鲟，科研人员已连续多年向长江放流人工繁育的幼鱼。","他的演讲深入浅出，既有理论高度，又贴近生活实际，令在场听众受益匪浅。","洛阳是著名的十三朝古都，当地的牡丹栽培始于隋、盛于唐，素有“洛阳牡丹甲天下”之称。"],"a":0,"type":"단어 안의 뜻 반복","why":"“超过”와 “以上”이 둘 다 ‘넘는다’는 뜻이라 겹친다.","fix":"据统计，参与此次问卷调查的市民中，半数以上的人表示曾在春节期间观看过线上庙会直播。","words":[["庙会","miàohuì","묘회(사찰 장터 축제)"],["中华鲟","zhōnghuáxún","중국철갑상어"],["繁育","fányù","번식시켜 기르다"],["深入浅出","shēn rù qiǎn chū","깊은 내용을 쉽게 풀다"],["受益匪浅","shòu yì fěi qiǎn","얻는 바가 크다"],["栽培","zāipéi","재배하다"]],"tr":["통계에 따르면 이번 설문에 참여한 시민 가운데 절반이 넘는 사람이 춘절 기간에 온라인 묘회 생중계를 본 적이 있다고 답했다.","멸종 위기의 중국철갑상어를 구하기 위해 연구진은 여러 해 연속으로 인공 번식한 치어를 장강에 방류해 왔다.","그의 강연은 어려운 내용을 쉽게 풀어내면서도 이론적 깊이와 생활 현실을 두루 갖추어 청중이 얻은 것이 많았다.","뤄양은 열세 왕조의 도읍으로 이름난 곳이며, 이곳의 모란 재배는 수나라 때 시작해 당나라 때 성행해 예로부터 ‘뤄양 모란이 천하제일’이라는 말이 있다."],"ow":[[["问卷","wènjuàn","설문지"],["半数","bànshù","절반"],["庙会","miàohuì","묘회"],["直播","zhíbō","생중계"]],[["拯救","zhěngjiù","구하다"],["濒危","bīnwēi","멸종 위기"],["中华鲟","zhōnghuáxún","중국철갑상어"],["繁育","fányù","번식시키다"]],[["深入浅出","shēn rù qiǎn chū","깊은 내용을 쉽게 풀다"],["贴近","tiējìn","가까이 다가가다"],["受益匪浅","shòu yì fěi qiǎn","얻는 바가 크다"]],[["古都","gǔdū","옛 도읍"],["牡丹","mǔdan","모란"],["栽培","zāipéi","재배하다"],["甲天下","jiǎ tiānxià","천하제일"]]]},{"o":["蚂蚁主要依靠释放信息素与同伴交流，这种化学物质能向同伴传达食物的位置或危险的信号。","这座城市在改造老工业区时，保留了大量厂房和烟囱，将其改建为艺术中心和创意园区。","在古代，女子年满十五岁要举行“及笄”之礼，标志着她已经成年。","作为文化遗产的守护者，每一位公民都有义务自觉履行保护文物的权利。"],"a":3,"type":"동사–목적어","why":"“履行”은 “义务”와 어울리고 “权利”는 “行使”와 어울린다.","fix":"作为文化遗产的守护者，每一位公民都应当自觉履行保护文物的义务。","words":[["信息素","xìnxīsù","페로몬"],["烟囱","yāncōng","굴뚝"],["及笄","jíjī","계례(여자 성년식)"],["守护","shǒuhù","지키다"],["履行","lǚxíng","이행하다"]],"tr":["개미는 주로 페로몬을 내뿜어 동료와 소통하며, 이 화학 물질은 먹이의 위치나 위험 신호를 동료에게 전달한다.","이 도시는 옛 공업 지구를 고치면서 공장 건물과 굴뚝을 많이 남겨 예술 센터와 창의 단지로 바꾸었다.","옛날에는 여자가 열다섯 살이 되면 ‘계례’라는 의식을 치렀는데, 이는 그녀가 성인이 되었음을 뜻했다.","문화유산을 지키는 사람으로서 모든 시민은 문화재를 보호하는 일을 스스로 실천할 의무가 있다."],"ow":[[["蚂蚁","mǎyǐ","개미"],["信息素","xìnxīsù","페로몬"],["传达","chuándá","전달하다"]],[["厂房","chǎngfáng","공장 건물"],["烟囱","yāncōng","굴뚝"],["园区","yuánqū","단지"]],[["及笄","jíjī","계례(여자 성년식)"],["标志","biāozhì","나타내다"]],[["守护者","shǒuhùzhě","지키는 사람"],["履行","lǚxíng","이행하다"],["义务","yìwù","의무"]]]}]];
